                                <div>
                                    <label className="text-[10px] text-gray-500 font-black uppercase tracking-widest block mb-2">Market Info</label>
                                    <textarea name="marketInfo" defaultValue={startup.marketInfo} rows="3" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#8B5CF6] transition-all resize-none" />
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-[10px] text-gray-500 font-black uppercase tracking-widest block mb-2">Growth</label>
                                        <input name="growth" defaultValue={startup.growth} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#8B5CF6] transition-all" />
                                    </div>
                                    <div>
                                        <label className="text-[10px] text-gray-500 font-black uppercase tracking-widest block mb-2">Revenue</label>
                                        <input name="revenue" defaultValue={startup.revenue} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#8B5CF6] transition-all" />
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-[10px] text-gray-500 font-black uppercase tracking-widest block mb-2">Demo Link</label>
                                        <input type="url" name="demoLink" defaultValue={startup.demoLink} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#8B5CF6] transition-all" />
                                    </div>
                                    <div>
                                        <label className="text-[10px] text-gray-500 font-black uppercase tracking-widest block mb-2">Pitch Deck Link</label>
                                        <input type="url" name="pitchDeckLink" defaultValue={startup.pitchDeckLink} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#8B5CF6] transition-all" />
                                    </div>
                                </div>
                                <button type="submit" className="w-full py-4 bg-[#8B5CF6] text-white font-black rounded-xl shadow-lg shadow-[#8B5CF6]/20 hover:bg-[#7C3AED] transition-all flex items-center justify-center gap-2 mt-4">
                                    <Save size={20} /> Save Changes
                                </button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* Page Header */}
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
                <div className="flex-1">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
                        <span className="w-fit px-3 py-1 bg-[#8B5CF6]/20 text-[#8B5CF6] text-[8px] md:text-[10px] font-black uppercase tracking-widest rounded-full border border-[#8B5CF6]/30">
                            Founder View
                        </span>
                        <div className="flex items-center gap-2">
                            <div className="w-24 sm:w-32 h-1.5 md:h-2 bg-white/5 rounded-full overflow-hidden border border-white/10">
                                <motion.div
                                    className="h-full bg-gradient-to-r from-[#8B5CF6] to-purple-400"
                                    initial={{ width: 0 }}
                                    animate={{ width: `${startup.profileCompletion}%` }}
                                />
                            </div>
                            <span className="text-gray-400 text-[10px] md:text-xs font-bold whitespace-nowrap">Profile Completion: {startup.profileCompletion}%</span>
                        </div>
                    </div>
                    <div className="group relative flex items-center gap-4">
                        <h1 className="text-3xl md:text-4xl lg:text-5xl font-black text-white tracking-tight leading-tight">
                            {startup.startupName} <span className="text-[#8B5CF6]">Platform</span>
                        </h1>
                        <button
                            onClick={() => {
                                const newName = prompt("Rename Startup:", startup.startupName);
                                if (newName) handleUpdate({ startupName: newName });
                            }}
                            className="p-2 bg-white/5 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white/10 shrink-0"
                        >
                            <Edit3 size={18} className="text-[#8B5CF6]" />
                        </button>
                    </div>
                </div>
                <div className="flex flex-col sm:flex-row gap-3">
                    <button className="flex items-center justify-center gap-2 px-5 py-3 md:py-2.5 bg-[#1E1E2F] text-white text-xs md:text-sm font-bold rounded-xl border border-white/5 hover:border-white/10 transition-all w-full sm:w-auto">
                        <Download size={18} /> Export Pitch Deck
                    </button>
                    <button
                        onClick={() => setIsEditModalOpen(true)}
                        className="px-5 py-3 md:py-2.5 bg-[#8B5CF6] text-white text-xs md:text-sm font-bold rounded-xl shadow-lg shadow-[#8B5CF6]/20 hover:bg-[#7C3AED] transition-all flex items-center justify-center gap-2 w-full sm:w-auto"
                    >
                        <Edit3 size={18} /> Edit Startup Info
                    </button>
                </div>
            </div>

            {/* Structured Summary Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <MetricItem label="Current Stage" value={startup.stage} onEdit={() => setIsEditModalOpen(true)} />
                <MetricItem label="Funding Goal" value={startup.fundingGoal || "No funding goal set."} onEdit={() => setIsEditModalOpen(true)} />
                <MetricItem label="Internal Team" value={`${startup.teamSize || 0} Members`} onEdit={() => setIsEditModalOpen(true)} />
                <MetricItem label="Burn Rate" value={`$${(startup.burnRate || 0).toLocaleString()} / Mo`} onEdit={() => setIsEditModalOpen(true)} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Core Identity */}
                <div className="lg:col-span-2 space-y-8">
                    {/* Problem & Solution */}
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5 space-y-8">
                        <div>
                            <SectionHeader icon={AlertCircle} title="Problem Statement">
                                {editingSection !== 'problemStatement' && (
                                    <button
                                        onClick={() => {
                                            setEditingSection('problemStatement');
                                            setEditValue(startup.problemStatement);
                                        }}
                                        className="text-[10px] font-black text-[#8B5CF6] uppercase tracking-widest hover:underline"
                                    >
                                        Edit
                                    </button>
                                )}
                            </SectionHeader>
                            {editingSection === 'problemStatement' ? (
                                <div className="space-y-4">
                                    <textarea
                                        autoFocus
                                        value={editValue}
                                        onChange={(e) => setEditValue(e.target.value)}
                                        className="w-full bg-white/5 border border-[#8B5CF6]/50 rounded-xl p-4 text-gray-300 focus:outline-none h-32"
                                    />
                                    <div className="flex gap-2 justify-end">
                                        <button onClick={() => setEditingSection(null)} className="px-4 py-2 text-xs font-bold text-gray-500">Cancel</button>
                                        <button onClick={() => handleInlineSave('problemStatement')} className="px-4 py-2 bg-[#8B5CF6] text-white text-xs font-bold rounded-lg shadow-lg">Save</button>
                                    </div>
                                </div>
                            ) : (
                                <p
                                    onClick={() => {
                                        setEditingSection('problemStatement');
                                        setEditValue(startup.problemStatement);
                                    }}
                                    className="text-gray-400 leading-relaxed font-medium cursor-pointer hover:text-gray-300 transition-colors"
                                >
                                    {startup.problemStatement || "No problem statement defined."}
                                </p>
                            )}
                        </div>

                        <div className="pt-8 border-t border-white/5">
                            <SectionHeader icon={Zap} title="Solution Overview">
                                {editingSection !== 'solutionOverview' && (
                                    <button
                                        onClick={() => {
                                            setEditingSection('solutionOverview');
                                            setEditValue(startup.solutionOverview);
                                        }}
                                        className="text-[10px] font-black text-[#8B5CF6] uppercase tracking-widest hover:underline"
                                    >
                                        Edit
                                    </button>
                                )}
                            </SectionHeader>
                            {editingSection === 'solutionOverview' ? (
                                <div className="space-y-4">
                                    <textarea
                                        autoFocus
                                        value={editValue}
                                        onChange={(e) => setEditValue(e.target.value)}
                                        className="w-full bg-white/5 border border-[#8B5CF6]/50 rounded-xl p-4 text-gray-300 focus:outline-none h-32"
                                    />
                                    <div className="flex gap-2 justify-end">
                                        <button onClick={() => setEditingSection(null)} className="px-4 py-2 text-xs font-bold text-gray-500">Cancel</button>
                                        <button onClick={() => handleInlineSave('solutionOverview')} className="px-4 py-2 bg-[#8B5CF6] text-white text-xs font-bold rounded-lg shadow-lg">Save</button>
                                    </div>
                                </div>
                            ) : (
                                <p
                                    onClick={() => {
                                        setEditingSection('solutionOverview');
                                        setEditValue(startup.solutionOverview);
                                    }}
                                    className="text-gray-400 leading-relaxed font-medium cursor-pointer hover:text-gray-300 transition-colors"
                                >
                                    {startup.solutionOverview || "No solution overview defined."}
                                </p>
                            )}
                        </div>
                    </div>

                    {/* Milestone Checklist */}
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5">
                        <SectionHeader icon={ClipboardList} title="Milestone Checklist">
                            <div className="flex items-center gap-4">
                                <div className="text-right">
                                    <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Execution Completion</p>
                                    <p className="text-lg font-black text-[#8B5CF6]">{executionPercentage}%</p>
                                </div>
                                <div className="w-12 h-12 rounded-full border-4 border-white/5 flex items-center justify-center relative">
                                    <svg className="w-full h-full -rotate-90">
                                        <circle
                                            cx="24"
                                            cy="24"
                                            r="18"
                                            fill="transparent"
                                            stroke="currentColor"
                                            strokeWidth="4"
                                            className="text-white/5"
                                        />
                                        <motion.circle
                                            cx="24"
                                            cy="24"
                                            r="18"
                                            fill="transparent"
                                            stroke="currentColor"
                                            strokeWidth="4"
                                            strokeDasharray={`${2 * Math.PI * 18}`}
                                            initial={{ strokeDashoffset: 2 * Math.PI * 18 }}
                                            animate={{ strokeDashoffset: (2 * Math.PI * 18) * (1 - executionPercentage / 100) }}
                                            className="text-[#8B5CF6]"
                                        />
                                    </svg>
                                </div>
                            </div>
                        </SectionHeader>

                        {startup.milestones.length === 0 ? (
                            <div className="py-12 flex flex-col items-center justify-center border-2 border-dashed border-white/5 rounded-2xl text-center">
                                <ClipboardList className="text-gray-700 mb-4" size={40} />
                                <p className="text-gray-500 font-bold">No milestones added yet.</p>
                                <p className="text-gray-600 text-xs mt-1">Start building your execution roadmap.</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {startup.milestones.map((item, i) => (
                                    <motion.div
                                        layout
                                        key={i}
                                        className={`group flex items-center justify-between p-4 rounded-xl border transition-all ${item.status === 'completed' ? 'bg-green-500/5 border-green-500/20' :
                                            item.status === 'in-progress' ? 'bg-[#8B5CF6]/5 border-[#8B5CF6]/20' :
                                                'bg-white/5 border-white/5 hover:border-white/10'
                                            }`}
                                    >
                                        <div className="flex items-center gap-4">
                                            <div className="relative">
                                                <select
                                                    value={item.status}
                                                    onChange={(e) => updateMilestone(item.id, { status: e.target.value })}
                                                    className="opacity-0 absolute inset-0 cursor-pointer w-full z-10"
                                                >
                                                    <option value="pending">Pending</option>
                                                    <option value="in-progress">In Progress</option>
                                                    <option value="completed">Completed</option>
                                                </select>
                                                <div className={`w-6 h-6 rounded-full flex items-center justify-center border transition-all ${item.status === 'completed' ? 'bg-green-500 border-green-500 text-white' :
                                                    item.status === 'in-progress' ? 'bg-[#8B5CF6] border-[#8B5CF6] text-white' :
                                                        'border-gray-700 hover:border-[#8B5CF6]'
                                                    }`}>
                                                    {item.status === 'completed' && <Check size={14} />}
                                                    {item.status === 'in-progress' && <Clock size={14} />}
                                                </div>
                                            </div>
                                            <div>
                                                <span className={`font-bold text-sm ${item.status === 'completed' ? 'text-gray-300' : 'text-white'}`}>{item.title}</span>
                                                <div className="flex gap-2 mt-1">
                                                    {item.status === 'completed' && <span className="text-[9px] font-black text-green-500 uppercase tracking-widest">Completed</span>}
                                                    {item.status === 'in-progress' && <span className="text-[9px] font-black text-[#8B5CF6] uppercase tracking-widest">In Progress</span>}
                                                    {item.status === 'pending' && <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Pending</span>}
                                                </div>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => deleteMilestone(item.id)}
                                            className="opacity-0 group-hover:opacity-100 p-2 text-gray-500 hover:text-red-500 transition-all"
                                        >
                                            <Trash2 size={16} />
                                        </button>
                                    </motion.div>
                                ))}
                            </div>
                        )}
                        <button
                            onClick={() => {
                                const t = prompt("Milestone title:");
                                if (t) addMilestone(t);
                            }}
                            className="w-full mt-6 py-3 border-2 border-dashed border-white/5 rounded-xl text-gray-500 hover:text-white hover:border-[#8B5CF6]/30 hover:bg-[#8B5CF6]/5 transition-all font-bold text-sm flex items-center justify-center gap-2"
                        >
                            <Plus size={18} /> Add New Milestone
                        </button>
                    </div>

                    {/* Mentorship Focus Areas (Shared with Mentor) */}
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.08] transition-opacity">
                            <Target size={120} />
                        </div>
                        <SectionHeader icon={Rocket} title="Mentorship Focus">
                            <div className="flex items-center gap-2">
                                <span className="px-2 py-0.5 bg-[#8B5CF6]/20 text-[#8B5CF6] text-[8px] font-black uppercase tracking-widest rounded border border-[#8B5CF6]/30">Collaborative</span>
                            </div>
                        </SectionHeader>

                        {mentor ? (
                            <div className="mb-8 p-6 bg-[#8B5CF6]/5 rounded-2xl border border-[#8B5CF6]/20 flex items-center gap-6">
                                <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-[#8B5CF6] to-indigo-600 flex items-center justify-center text-2xl font-black text-white shadow-xl flex-shrink-0">
                                    {mentorName[0]}
                                </div>
                                <div className="flex-1">
                                    <div className="flex items-center gap-2 mb-1">
                                        <h4 className="text-white font-black text-lg">{mentorName}</h4>
                                        <span className="px-2 py-0.5 bg-green-500/10 text-green-400 text-[8px] font-black uppercase tracking-widest rounded border border-green-500/20">Active Mentor</span>
                                    </div>
                                    <p className="text-xs text-gray-500 font-medium line-clamp-1">{mentor.expertise || 'General Strategy'} ÔÇó {mentor.sector || 'Expert'}</p>
                                    <div className="flex items-center gap-4 mt-3">
                                        <button
                                            onClick={() => navigate(`/${role}/messages`, { state: { openChat: { startupId: startup.startupId, type: 'mentor' } } })}
                                            className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-[#8B5CF6] hover:text-[#7C3AED] transition-all"
                                        >
                                            <MessageSquare size={12} /> Message Mentor
                                        </button>
                                        <div className="h-3 w-px bg-white/10" />
                                        <button
                                            onClick={() => navigate(`/${role}/mentors#my-mentor`)}
                                            className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-white transition-all"
                                        >
                                            View Profile
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="mb-8 p-6 bg-yellow-500/5 rounded-2xl border border-yellow-500/10 flex items-center gap-4">
                                <AlertCircle className="text-yellow-500 flex-shrink-0" size={24} />
                                <div>
                                    <p className="text-white font-bold text-sm">No mentor assigned yet</p>
                                    <p className="text-[10px] text-gray-500 font-medium">Request a mentor in the Discover Network to accelerate your growth.</p>
                                </div>
                            </div>
                        )}

                        <p className="text-xs text-gray-500 font-medium mb-6 leading-relaxed">
                            These focus areas are set in collaboration with your mentor to guide your current execution sprint.
                        </p>

                        {!Array.isArray(startup.focusAreas) || startup.focusAreas.length === 0 ? (
                            <div className="py-8 text-center bg-white/5 rounded-xl border border-dashed border-white/10">
                                <p className="text-gray-500 text-xs font-bold">No mentorship focus areas defined yet.</p>
                                <p className="text-[9px] text-gray-600 uppercase font-black mt-2">Will be updated by your assigned mentor</p>
                            </div>
                        ) : (
                            <div className="flex flex-wrap gap-3">
                                {startup.focusAreas.map((area, i) => (
                                    <div key={i} className="flex items-center gap-2 px-4 py-2 bg-[#8B5CF6]/10 border border-[#8B5CF6]/20 rounded-xl text-white font-bold text-sm group/tag">
                                        <Zap size={14} className="text-[#8B5CF6]" />
                                        {area}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Right Column: Execution & Needs */}
                <div className="space-y-8">
                    {/* Target Audience */}
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5">
                        <SectionHeader icon={Target} title="Target Audience">
                            <button
                                onClick={() => {
                                    setEditingSection('audience');
                                    setEditValue(startup.targetAudience.join('\n'));
                                }}
                                className="text-[10px] font-black text-[#8B5CF6] uppercase tracking-widest hover:underline"
                            >
                                Edit
                            </button>
                        </SectionHeader>
                        {editingSection === 'audience' ? (
                            <div className="space-y-4">
                                <p className="text-[10px] text-gray-500 font-bold italic">One audience per line</p>
                                <textarea
                                    autoFocus
                                    value={editValue}
                                    onChange={(e) => setEditValue(e.target.value)}
                                    className="w-full bg-white/5 border border-[#8B5CF6]/50 rounded-xl p-4 text-gray-300 focus:outline-none h-32"
                                />
                                <div className="flex gap-2 justify-end">
                                    <button onClick={() => setEditingSection(null)} className="px-4 py-2 text-xs font-bold text-gray-500">Cancel</button>
                                    <button onClick={() => handleInlineSave('audience')} className="px-4 py-2 bg-[#8B5CF6] text-white text-xs font-bold rounded-lg shadow-lg">Save</button>
                                </div>
                            </div>
                        ) : (
                            <ul className="space-y-3">
                                {startup.targetAudience.length === 0 ? (
                                    <p className="text-gray-500 text-sm italic">No target audience defined.</p>
                                ) : (
                                    startup.targetAudience.map((t, i) => (
                                        <li key={i} className="flex items-center group justify-between">
                                            <div className="flex items-center gap-3">
                                                <div className="w-1.5 h-1.5 bg-[#8B5CF6] rounded-full" />
                                                <span className="text-sm font-bold text-gray-300">{t}</span>
                                            </div>
                                            <button
                                                onClick={() => {
                                                    const updated = startup.targetAudience.filter((_, idx) => idx !== i);
                                                    handleUpdate({ targetAudience: updated });
                                                }}
                                                className="opacity-0 group-hover:opacity-100 text-gray-600 hover:text-red-400"
                                            >
                                                <X size={12} />
                                            </button>
                                        </li>
                                    ))
                                )}
                                <button
                                    onClick={() => {
                                        const newAud = prompt("Add target audience:");
                                        if (newAud) handleUpdate({ targetAudience: [...startup.targetAudience, newAud] });
                                    }}
                                    className="text-[10px] font-black text-[#8B5CF6] uppercase tracking-widest mt-4 flex items-center gap-1 hover:gap-2 transition-all"
                                >
                                    <Plus size={12} /> Add New
                                </button>
                            </ul>
                        )}
                    </div>

                    {/* Skill Gap Highlight */}
                    <div className={`${startup.skillGapFilled ? 'bg-green-500/5 border-green-500/10' : 'bg-[#8B5CF6]/10 border-[#8B5CF6]/20'} p-8 rounded-2xl border relative overflow-hidden group transition-all duration-500`}>
                        <div className={`absolute -top-4 -right-4 w-24 h-24 ${startup.skillGapFilled ? 'bg-green-500/20' : 'bg-[#8B5CF6]/20'} blur-3xl rounded-full`} />
                        <SectionHeader icon={Users} title={startup.skillGapFilled ? "Team Status" : "Skill Gap"} />

                        {startup.skillGapFilled ? (
                            <div className="flex flex-col items-center text-center py-4">
                                <motion.div
                                    initial={{ scale: 0 }}
                                    animate={{ scale: 1 }}
                                    className="w-16 h-16 rounded-full bg-green-500/20 flex items-center justify-center text-green-400 mb-4 ring-2 ring-green-500/50"
                                >
                                    <CheckCircle2 size={32} />
                                </motion.div>
                                <p className="text-white font-black text-xl mb-1">Team Fully Formed <span className="text-green-400">Ô£à</span></p>
                                <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">No active skill gaps</p>
                                <button
                                    onClick={() => handleUpdate({ skillGapFilled: false })}
                                    className="mt-6 text-[10px] font-black text-gray-500 uppercase tracking-widest hover:text-white"
                                >
                                    Add new gap
                                </button>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {!startup.skillGap ? (
                                    <div className="py-4 text-center">
                                        <p className="text-gray-500 text-sm font-medium">Define your missing role to improve team strength.</p>
                                        <button
                                            onClick={() => {
                                                const gap = prompt("What role is missing?");
                                                if (gap) handleUpdate({ skillGap: gap });
                                            }}
                                            className="mt-4 px-4 py-2 border border-[#8B5CF6]/30 text-[#8B5CF6] text-xs font-black rounded-lg hover:bg-[#8B5CF6]/10 transition-all"
                                        >
                                            Add Skill Gap
                                        </button>
                                    </div>
                                ) : (
                                    <>
                                        <div className="p-4 bg-white/5 rounded-xl border border-white/10 group-hover:border-[#8B5CF6]/30 transition-all">
                                            <div className="flex justify-between items-start mb-2 gap-2">
                                                <p className="text-[9px] text-gray-500 font-bold uppercase tracking-widest font-black shrink-0">Looking For:</p>
                                                <div className="relative shrink-0">
                                                    <select
                                                        value={startup.skillGapPriority}
                                                        onChange={(e) => handleUpdate({ skillGapPriority: e.target.value })}
                                                        className="absolute inset-0 opacity-0 cursor-pointer w-full"
                                                    >
                                                        <option value="Low">Low</option>
                                                        <option value="Medium">Medium</option>
                                                        <option value="High">High</option>
                                                    </select>
                                                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest whitespace-nowrap ${startup.skillGapPriority === 'High' ? 'bg-red-500/20 text-red-500' :
                                                        startup.skillGapPriority === 'Medium' ? 'bg-yellow-500/20 text-yellow-500' :
                                                            'bg-blue-500/20 text-blue-500'
                                                        }`}>
                                                        {startup.skillGapPriority} Priority
                                                    </span>
                                                </div>
                                            </div>
                                            <div className="flex items-center justify-between gap-3">
                                                <p className="text-white font-black text-lg truncate">{startup.skillGap}</p>
                                                <button
                                                    onClick={() => {
                                                        const newGap = prompt("Update skill gap:", startup.skillGap);
                                                        if (newGap) handleUpdate({ skillGap: newGap });
                                                    }}
                                                    className="p-1 hover:bg-white/10 rounded shrink-0"
                                                >
                                                    <Edit3 size={14} className="text-gray-500" />
                                                </button>
                                            </div>
                                        </div>
                                        <div className="space-y-3">
                                            <button
                                                onClick={() => handleUpdate({ skillGapFilled: true })}
                                                className="w-full py-3 bg-[#8B5CF6] text-white text-xs font-black rounded-xl shadow-lg shadow-[#8B5CF6]/20 hover:bg-[#7C3AED] transition-all flex items-center justify-center gap-2"
                                            >
                                                <CheckCircle2 size={16} /> Mark as Filled
                                            </button>
                                            <button className="w-full py-3 border border-[#8B5CF6]/30 text-[#8B5CF6] text-xs font-black rounded-xl hover:bg-[#8B5CF6]/10 transition-all">Match with Candidates</button>
                                        </div>
                                    </>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Documents */}
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5">
                        <SectionHeader icon={FileText} title="Documents">
                            <input
                                type="file"
                                ref={fileInputRef}
                                className="hidden"
                                onChange={handleFileUpload}
                            />
                            <button
                                onClick={() => fileInputRef.current?.click()}
                                className="text-[10px] font-black text-[#8B5CF6] uppercase tracking-widest hover:underline flex items-center gap-1"
                            >
                                <Plus size={12} /> Upload
                            </button>
                        </SectionHeader>

                        {startup.documents.length === 0 ? (
                            <div className="py-8 text-center flex flex-col items-center">
                                <FileText className="text-gray-700 mb-2" size={32} />
                                <p className="text-gray-500 text-xs font-bold">No documents uploaded.</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {startup.documents.map((doc, i) => (
                                    <div key={i} className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/5 group hover:border-[#8B5CF6]/30 transition-all">
                                        <div className="flex items-center gap-3 overflow-hidden">
                                            <div className="w-8 h-8 rounded-lg bg-[#8B5CF6]/10 flex items-center justify-center text-[#8B5CF6] shrink-0">
                                                <FileText size={16} />
                                            </div>
                                            <div className="overflow-hidden">
                                                <p className="text-xs font-bold text-white truncate max-w-[140px]">{doc.name}</p>
                                                <p className="text-[8px] text-gray-500 font-black uppercase tracking-widest">{doc.size}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => {
                                                    const newName = prompt("Rename document:", doc.name);
                                                    if (newName) {
                                                        renameDocument(i, newName);
                                                        showToast("Renamed successfully");
                                                    }
                                                }}
                                                className="p-1.5 hover:bg-white/10 rounded-lg text-gray-400 hover:text-white"
                                            >
                                                <Edit3 size={12} />
                                            </button>
                                            <button
                                                onClick={() => {
                                                    if (confirm(`Delete ${doc.name}?`)) {
                                                        deleteDocument(i);
                                                        showToast("Document deleted");
                                                    }
                                                }}
                                                className="p-1.5 hover:bg-white/10 rounded-lg text-gray-400 hover:text-red-400"
                                            >
                                                <Trash2 size={12} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                        <button
                            onClick={() => fileInputRef.current?.click()}
                            className="w-full mt-6 py-3 border border-dashed border-white/10 hover:border-[#8B5CF6]/30 hover:bg-[#8B5CF6]/5 rounded-xl text-gray-500 text-xs font-bold transition-all flex items-center justify-center gap-2"
                        >
                            <Upload size={14} /> Upload New Document
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default MyStartup;

import React, { useState } from 'react';
import {
    Calendar as CalendarIcon,
    Clock,
    CheckCircle2,
    XCircle,
    MessageSquare,
    Calendar,
    ChevronLeft,
    Video,
    User,
    Plus,
    X,
    ExternalLink
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useStartup } from '../../../context/StartupContext';
import { getSystem } from '../../../utils/system';

const RequestSessionModal = ({ onClose, onRequest }) => {
    const [date, setDate] = useState('');
    const [time, setTime] = useState('');
    const [topic, setTopic] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        onRequest(date, time, topic);
        onClose();
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md"
        >
            <motion.div
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                exit={{ scale: 0.9, y: 20 }}
                className="bg-[#1E1E2F] w-full max-w-lg rounded-3xl border border-white/10 shadow-2xl p-8"
            >
                <div className="flex justify-between items-start mb-8">
                    <div>
                        <h2 className="text-2xl font-black text-white mb-1">Request Session</h2>
                        <p className="text-[#8B5CF6] font-bold text-sm">Propose a time for your next call</p>
                    </div>
                    <button onClick={onClose} className="p-2 bg-white/5 hover:bg-white/10 rounded-xl transition-all">
                        <X size={20} className="text-gray-400" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div>
                        <label className="text-xs font-black text-gray-500 uppercase tracking-widest mb-3 block">Proposed Date</label>
                        <input
                            required
                            type="date"
                            value={date}
                            onChange={e => setDate(e.target.value)}
                            className="w-full bg-[#0F0F14] border border-white/10 rounded-2xl p-4 text-white font-medium focus:outline-none focus:border-[#8B5CF6]/50 transition-all"
                        />
                    </div>
                    <div>
                        <label className="text-xs font-black text-gray-500 uppercase tracking-widest mb-3 block">Proposed Time</label>
                        <input
                            required
                            type="time"
                            value={time}
                            onChange={e => setTime(e.target.value)}
                            className="w-full bg-[#0F0F14] border border-white/10 rounded-2xl p-4 text-white font-medium focus:outline-none focus:border-[#8B5CF6]/50 transition-all"
                        />
                    </div>
                    <div>
                        <label className="text-xs font-black text-gray-500 uppercase tracking-widest mb-3 block">Topic / Agenda</label>
                        <input
                            value={topic}
                            onChange={e => setTopic(e.target.value)}
                            placeholder="What do you want to discuss?"
                            className="w-full bg-[#0F0F14] border border-white/10 rounded-2xl p-4 text-white font-medium focus:outline-none focus:border-[#8B5CF6]/50 transition-all placeholder:text-gray-700"
                        />
                    </div>
                    <div className="flex gap-4">
                        <button
                            type="submit"
                            className="flex-1 py-4 bg-[#8B5CF6] hover:bg-[#7C3AED] text-white text-xs font-black uppercase tracking-widest rounded-2xl shadow-xl shadow-[#8B5CF6]/20 transition-all flex items-center justify-center gap-2"
                        >
                            <CalendarIcon size={16} /> Send Request
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-8 py-4 bg-white/5 text-gray-400 hover:text-white text-xs font-black uppercase tracking-widest rounded-2xl transition-all border border-white/5"
                        >
                            Cancel
                        </button>
                    </div>
                </form>
            </motion.div>
        </motion.div>
    );
};

const SessionItem = ({ session }) => {
    // Get mentor name from system state
    const system = getSystem();
    const mentor = system.users?.[session.mentorId];
    const mentorName = mentor?.name || mentor?.email?.split('@')[0] || 'Unknown Mentor';
    const mentorTitle = mentor?.title || 'Expert Mentor';

    return (
        <div className="bg-[#1E1E2F] p-6 rounded-2xl border border-white/5 hover:border-[#8B5CF6]/30 transition-all group">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div className="flex gap-4">
                    <div className="w-12 h-12 rounded-xl bg-gradient-to-tr from-[#8B5CF6] to-indigo-500 flex items-center justify-center font-bold text-white shadow-lg border border-white/10 flex-shrink-0">
                        {mentorName?.[0] || '?'}
                    </div>
                    <div>
                        <h4 className="text-white font-bold">{mentorName}</h4>
                        <p className="text-[#8B5CF6] text-[10px] font-black uppercase tracking-widest">{mentorTitle}</p>
                        <div className="flex items-center gap-4 mt-2 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                            <span className="flex items-center gap-1.5"><CalendarIcon size={12} className="text-[#8B5CF6]" /> {session.date}</span>
                            <span className="flex items-center gap-1.5"><Clock size={12} className="text-[#8B5CF6]" /> {session.time}</span>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {session.status === 'upcoming' && (
                        <button className="flex items-center gap-2 px-5 py-3 bg-[#8B5CF6] hover:bg-[#7C3AED] text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-[#8B5CF6]/20 transition-all">
                            <Video size={14} /> Join Call
                        </button>
                    )}
                    <button className="p-3 text-gray-500 hover:text-white bg-white/5 hover:bg-white/10 rounded-xl transition-all border border-white/5">
                        <MessageSquare size={18} />
                    </button>
                    <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 ${session.status === 'completed' ? 'bg-green-500/10 text-green-400 border border-green-500/20' :
                        session.status === 'upcoming' ? 'bg-[#8B5CF6]/10 text-[#8B5CF6] border border-[#8B5CF6]/20' :
                            session.status === 'requested' ? 'bg-orange-500/10 text-orange-400 border border-orange-500/20' :
                                'bg-red-500/10 text-red-400 border border-red-500/20'
                        }`}>
                        {session.status === 'completed' ? <CheckCircle2 size={14} /> :
                            session.status === 'upcoming' ? <Clock size={14} /> :
                                session.status === 'requested' ? <CalendarIcon size={14} /> : <XCircle size={14} />}
                        {session.status}
                    </span>
                </div>
            </div>

            {session.status === 'completed' && session.notes && (
                <div className="mt-6 pt-6 border-t border-white/5">
                    <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                        <CheckCircle2 size={12} className="text-green-400" /> Mentor Feedback
                    </p>
                    <p className="text-sm text-gray-400 leading-relaxed italic">"{session.notes}"</p>
                    {session.actionItems && session.actionItems.length > 0 && (
                        <div className="mt-4 flex flex-wrap gap-2">
                            {session.actionItems.map((item, idx) => (
                                <span key={idx} className="px-2 py-1 bg-white/5 border border-white/10 rounded text-[10px] text-gray-400 font-bold">
                                    ÔÇó {item}
                                </span>
                            ))}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

const Sessions = () => {
    const { sessions, requestSession, startup } = useStartup();
    const [activeTab, setActiveTab] = useState('upcoming');
    const [showRequestModal, setShowRequestModal] = useState(false);

    // Filter sessions based on tab
    const filteredSessions = sessions.filter(s => s.status === activeTab);

    return (
        <div className="space-y-10 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h1 className="text-4xl md:text-5xl font-black text-white tracking-tight">
                        Mentorship <span className="text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-500">Sessions</span>
                    </h1>
                    <p className="text-gray-500 mt-2 font-medium">Review feedback and join upcoming advisory calls.</p>
                </div>

                <div className="flex flex-col md:flex-row items-center gap-4">
                    <div className="bg-[#1E1E2F] p-1.5 rounded-2xl border border-white/5 flex gap-2 w-fit">
                        {['requested', 'upcoming', 'completed', 'cancelled'].map((tab) => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab)}
                                className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab
                                    ? 'bg-[#8B5CF6] text-white shadow-lg shadow-[#8B5CF6]/20'
                                    : 'text-gray-500 hover:text-white hover:bg-white/5'
                                    }`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>

                    {startup?.mentorAssigned && (
                        <button
                            onClick={() => setShowRequestModal(true)}
                            className="px-6 py-4 bg-white/5 hover:bg-[#8B5CF6] text-white text-[10px] font-black uppercase tracking-widest rounded-2xl border border-white/5 hover:border-[#8B5CF6] transition-all flex items-center gap-2"
                        >
                            <Plus size={16} /> Request Session
                        </button>
                    )}
                </div>
            </div>

            {/* Sessions List */}
            <div className="space-y-4 max-w-4xl">
                {filteredSessions.length > 0 ? (
                    filteredSessions.map((session) => (
                        <SessionItem key={session.id} session={session} />
                    ))
                ) : (
                    <div className="py-20 bg-[#1E1E2F] rounded-3xl border border-dashed border-white/10 flex flex-col items-center justify-center text-center">
                        <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mb-6 text-gray-600">
                            <CalendarIcon size={32} />
                        </div>
                        <h3 className="text-xl font-black text-white mb-2">No {activeTab} sessions</h3>
                        <p className="text-gray-500 font-medium">Your mentor will schedule sessions here after acceptance.</p>
                    </div>
                )}
            </div>

            {/* Info Card */}
            <div className="max-w-4xl p-6 bg-[#8B5CF6]/5 rounded-2xl border border-[#8B5CF6]/20 flex items-start gap-4">
                <div className="p-2 bg-[#8B5CF6]/20 rounded-lg text-[#8B5CF6]">
                    <User size={20} />
                </div>
                <div>
                    <h4 className="text-white font-black text-sm mb-1">How it works</h4>
                    <p className="text-xs text-gray-400 font-medium leading-relaxed">
                        Sessions are scheduled by your mentor. Once a session is marked as completed, you can view the feedback and action items assigned to you here. Use these to update your milestones and track execution progress.
                    </p>
                </div>
            </div>

            {/* Modals */}
            <AnimatePresence>
                {showRequestModal && (
                    <RequestSessionModal
                        onClose={() => setShowRequestModal(false)}
                        onRequest={requestSession}
                    />
                )}
            </AnimatePresence>
        </div>
    );
};

export default Sessions;

import React from 'react';
import { motion } from 'framer-motion';
import {
    Users,
    Rocket,
    TrendingUp,
    DollarSign,
    PieChart,
    BarChart3,
    Activity,
    Target,
    ArrowUpRight,
    ArrowDownRight,
    Globe,
    Zap
} from 'lucide-react';

import { useIncubator } from '../../../context/IncubatorContext';

const Analytics = () => {
    const { analytics, pipeline, mentors, cohorts } = useIncubator();

    const mainStats = [
        { label: 'Ecosystem Portfolio', value: analytics.totalStartups, trend: '+4', positive: true, icon: Rocket },
        { label: 'Avg Execution Score', value: `${analytics.avgExecutionScore}%`, trend: '+2.4%', positive: true, icon: TrendingUp },
        { label: 'Active Cohorts', value: cohorts.filter(c => c.status === 'active').length, trend: 'Stable', positive: true, icon: Target },
        { label: 'Expert Network', value: mentors.length, trend: '+12%', positive: true, icon: Users },
    ];

    // Calculate sector distribution dynamically
    const sectors = [...new Set(pipeline.map(s => s.sector))];
    const sectorData = sectors.map((s, i) => {
        const count = pipeline.filter(p => p.sector === s).length;
        const percentage = Math.round((count / pipeline.length) * 100);
        const colors = ['#8B5CF6', '#7C3AED', '#6366F1', '#4F46E5', '#312E81'];
        return { label: s, value: percentage, color: colors[i % colors.length] };
    });

    return (
        <div className="space-y-8 pb-10">
            <div>
                <h1 className="text-2xl font-bold text-white mb-1">Ecosystem Analytics</h1>
                <p className="text-sm text-gray-400">Quantitative insights into incubator performance and startup traction</p>
            </div>

            {/* Performance Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {mainStats.map((stat, index) => (
                    <motion.div
                        key={index}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.1 }}
                        className="bg-[#1E1E2F] border border-white/5 rounded-2xl p-6 hover:border-[#8B5CF6]/30 transition-all group"
                    >
                        <div className="flex justify-between items-start mb-4">
                            <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-[#8B5CF6] group-hover:scale-110 transition-transform">
                                <stat.icon size={20} />
                            </div>
                            <div className={`flex items-center gap-1 text-[10px] font-black uppercase tracking-widest ${stat.positive ? 'text-emerald-400' : 'text-rose-400'}`}>
                                {stat.positive ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />}
                                {stat.trend}
                            </div>
                        </div>
                        <h3 className="text-2xl font-bold text-white mb-1 tracking-tight">{stat.value}</h3>
                        <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">{stat.label}</p>
                    </motion.div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Sector Distribution */}
                <div className="lg:col-span-1 bg-[#1E1E2F] border border-white/5 rounded-3xl p-8 space-y-8 relative overflow-hidden">
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-sm font-black uppercase tracking-widest text-[#8B5CF6] flex items-center gap-2">
                            <PieChart size={16} /> Sector Composition
                        </h3>
                    </div>

                    <div className="relative w-48 h-48 mx-auto">
                        <svg className="w-full h-full transform -rotate-90">
                            {sectorData.map((d, i) => {
                                let offset = 0;
                                for (let j = 0; j < i; j++) offset += sectorData[j].value;
                                return (
                                    <circle
                                        key={i}
                                        cx="24"
                                        cy="24"
                                        r="18"
                                        fill="transparent"
                                        stroke={d.color}
                                        strokeWidth="4"
                                        strokeDasharray={`${d.value} ${100 - d.value}`}
                                        strokeDashoffset={-offset}
                                        className="transition-all duration-1000"
                                        viewBox="0 0 48 48"
                                    />
                                );
                            })}
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-3xl font-black text-white">{pipeline.length}</span>
                            <span className="text-[8px] text-gray-500 uppercase font-black tracking-widest">Startups</span>
                        </div>
                    </div>

                    <div className="space-y-3">
                        {sectorData.map((d, i) => (
                            <div key={i} className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <div className="w-2 h-2 rounded-full" style={{ backgroundColor: d.color }} />
                                    <span className="text-xs font-medium text-gray-300">{d.label}</span>
                                </div>
                                <span className="text-xs font-bold text-white">{d.value}%</span>
                            </div>
                        ))}
                        {sectorData.length === 0 && (
                            <p className="text-center text-xs text-gray-500 italic">No sector data available</p>
                        )}
                    </div>
                </div>

                {/* Performance Matrix */}
                <div className="lg:col-span-2 bg-[#1E1E2F] border border-white/5 rounded-3xl p-8 space-y-8">
                    <div className="flex items-center justify-between">
                        <h3 className="text-sm font-black uppercase tracking-widest text-[#8B5CF6] flex items-center gap-2">
                            <BarChart3 size={16} /> Portfolio Health Matrix
                        </h3>
                    </div>

                    <div className="h-64 flex items-end justify-between gap-4 px-2">
                        {cohorts.map((cohort, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center gap-3 group">
                                <div className="w-full relative">
                                    <motion.div
                                        initial={{ height: 0 }}
                                        animate={{ height: `${cohort.progress}%` }}
                                        transition={{ delay: i * 0.1, duration: 1 }}
                                        className="w-full bg-gradient-to-t from-[#8B5CF6]/20 to-[#8B5CF6] rounded-t-xl relative group-hover:to-[#7C3AED] transition-all"
                                    >
                                        <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-[#8B5CF6] text-white text-[10px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">
                                            {cohort.progress}%
                                        </div>
                                    </motion.div>
                                </div>
                                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest truncate w-full text-center">{cohort.name.split(' ')[0]}</span>
                            </div>
                        ))}
                    </div>

                    <div className="grid grid-cols-3 gap-6 pt-6 border-t border-white/5">
                        <div className="text-center">
                            <p className="text-xs text-gray-500 font-bold uppercase mb-1">Graduated</p>
                            <p className="text-lg font-bold text-white">{cohorts.filter(c => c.status === 'completed').length}</p>
                        </div>
                        <div className="text-center border-x border-white/5">
                            <p className="text-xs text-gray-500 font-bold uppercase mb-1">High Potential</p>
                            <p className="text-lg font-bold text-white">{pipeline.filter(s => s.executionScore > 80).length}</p>
                        </div>
                        <div className="text-center">
                            <p className="text-xs text-gray-500 font-bold uppercase mb-1">Avg Execution</p>
                            <p className="text-lg font-bold text-white">{analytics.avgExecutionScore}%</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Regional & Impact Stats */}
            <div className="bg-[#1E1E2F] border border-white/5 rounded-3xl p-8 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                    <Globe size={180} className="text-[#8B5CF6]" />
                </div>
                <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-6">
                        <h3 className="text-sm font-black uppercase tracking-widest text-[#8B5CF6] flex items-center gap-2">
                            <Zap size={16} /> Regional Impact
                        </h3>
                        <div className="space-y-4">
                            {[...new Set(pipeline.map(s => s.location || 'Remote'))].slice(0, 4).map((loc, i) => {
                                const count = pipeline.filter(p => (p.location || 'Remote') === loc).length;
                                return (
                                    <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-[#8B5CF6]/10 flex items-center justify-center text-[#8B5CF6] font-bold text-xs border border-[#8B5CF6]/20">
