        if (settings) setLocalSettings(settings);
    }, [settings]);

    const toggleNotification = (key) => {
        const updated = {
            ...localSettings,
            notifications: {
                ...localSettings.notifications,
                [key]: !localSettings.notifications[key]
            }
        };
        setLocalSettings(updated);
    };

    const handleSave = () => {
        updateSettings(localSettings);
