                    </div>
                ) : (
                    <div className="p-2 rounded-lg bg-white/5 text-gray-600 border border-white/5 flex items-center gap-1">
                        <Minus size={12} />
                        <span className="text-[10px] font-black uppercase">No data</span>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-2 gap-4 mb-6">
