                )}

                {isPreviewModalOpen && (
                    <div className="fixed inset-0 z-[120] flex items-center justify-center md:p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setIsPreviewModalOpen(false)} />
                        <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} className="relative w-full h-full md:h-auto md:max-w-2xl bg-[#0F0F14] border border-white/10 md:rounded-3xl p-1 overflow-hidden shadow-2xl overflow-y-auto">
                            <div className="bg-[#1E1E2F] md:rounded-[22px] p-6 md:p-8 h-full md:h-auto overflow-y-auto">
                                <div className="flex justify-between items-start mb-8 md:mb-12">
                                    <div className="flex-1">
                                        <div className="flex items-center gap-3 mb-4">
                                            <span className="px-2 py-0.5 bg-[#8B5CF6]/20 text-[#8B5CF6] text-[8px] font-black uppercase tracking-widest rounded border border-[#8B5CF6]/30">Vanguard Verified</span>
                                        </div>
                                        <h2 className="text-2xl md:text-4xl font-black text-white mb-2">{startup.startupName}</h2>
                                        <p className="text-xs md:text-gray-500 font-bold">{startup.stage} Stage ÔÇó {startup.expertiseSector || 'Tech'}</p>
                                    </div>
                                    <button onClick={() => setIsPreviewModalOpen(false)} className="p-2 bg-white/5 rounded-xl text-gray-400 hover:text-white transition-colors transition-colors"><X size={24} /></button>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                                    <div className="space-y-6">
                                        <div>
                                            <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">The Problem</h4>
                                            <p className="text-sm text-gray-300 leading-relaxed">{startup.problemStatement}</p>
                                        </div>
                                        <div>
                                            <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Execution Score</h4>
                                            <div className="flex items-center gap-4">
                                                <div className="text-3xl font-black text-[#8B5CF6]">{executionScore}%</div>
                                                <div className="flex-1 h-2 bg-white/5 rounded-full overflow-hidden">
                                                    <div className="h-full bg-[#8B5CF6]" style={{ width: `${executionScore}%` }} />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="bg-white/5 rounded-2xl p-6 border border-white/5">
                                        <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4">Core Metrics</h4>
                                        <div className="space-y-4">
                                            <div className="flex justify-between items-center">
                                                <span className="text-xs text-gray-400">Active Users</span>
                                                <span className="text-sm font-bold text-white">{(startup?.activeUsers || 0).toLocaleString()}</span>
                                            </div>
                                            <div className="flex justify-between items-center">
                                                <span className="text-xs text-gray-400">Team Size</span>
                                                <span className="text-sm font-bold text-white">{startup?.teamSize || 1}</span>
                                            </div>
                                            <div className="flex justify-between items-center">
                                                <span className="text-xs text-gray-400">Milestones</span>
                                                <span className="text-sm font-bold text-white">{(startup?.milestones || []).length} defined</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <button className="w-full py-4 bg-white text-black font-black rounded-xl hover:bg-gray-200 transition-colors">
                                    Contact Founder
                                </button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default DashboardHome;

import React, { useEffect, useMemo, useState } from 'react';
import {
    MapPin,
    Calendar,
    TrendingUp,
    Search,
    Filter,
    ChevronRight,
    Globe,
    Zap,
    X,
    Shield,
    CheckCircle2,
    RefreshCw,
    Target,
    Users,
    Clock,
    AlertCircle,
    Layers,
    CircleDot
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../../../context/AuthContext';
import { useStartup } from '../../../context/StartupContext';
import { getSystem, normalizeApplication, saveSystem } from '../../../utils/system';

const normalizeToArray = (value) => {
    if (Array.isArray(value)) return value.filter(Boolean);
    if (typeof value === 'string') {
        return value
            .split(',')
            .map(item => item.trim())
            .filter(Boolean);
    }
    if (!value) return [];
    return [String(value)];
};

const parseDate = (value) => {
    if (!value) return null;
    const date = new Date(value);
    return Number.isFinite(date.getTime()) ? date : null;
};

const formatDate = (value) => {
    const date = parseDate(value);
    return date ? date.toLocaleDateString() : 'TBD';
};

const getCohortStatus = (cohort) => {
    const now = new Date();
    const start = parseDate(cohort?.startDate);
    const end = parseDate(cohort?.endDate);

    if (start && end) {
        if (now < start) return 'upcoming';
        if (now > end) return 'completed';
        return 'active';
    }

    if (cohort?.status === 'active' || cohort?.status === 'completed' || cohort?.status === 'upcoming') {
        return cohort.status;
    }

    return 'upcoming';
};

const getCohortCurrentCapacity = (cohort, applications) => {
    const directCapacity = Array.isArray(cohort?.startupIds) ? cohort.startupIds.length : 0;
    if (directCapacity > 0) return directCapacity;

    return applications.filter(app => app.status === 'accepted' && app.cohortId === cohort.id).length;
};

const Incubators = () => {
    const { user } = useAuth();
    const { startup } = useStartup();

    const [loading, setLoading] = useState(true);
    const [systemState, setSystemState] = useState({
        incubators: [],
        cohorts: [],
        applications: [],
        startups: []
    });
    const [selectedIncubator, setSelectedIncubator] = useState(null);

    const [searchQuery, setSearchQuery] = useState('');
    const [filters, setFilters] = useState({
        sector: 'All',
        stages: [],
        location: 'All',
        verifiedOnly: false
    });
    const [isFilterMenuOpen, setIsFilterMenuOpen] = useState(false);

    useEffect(() => {
        const refreshData = () => {
            setLoading(true);
            try {
                const system = getSystem();
                setSystemState({
                    incubators: system.incubators || [],
                    cohorts: system.cohorts || [],
                    applications: system.applications || [],
                    startups: system.startups || []
                });
            } catch (error) {
                console.error('Error loading incubator discovery data:', error);
            } finally {
                setLoading(false);
            }
        };

        refreshData();
        const handleStorage = () => refreshData();
        window.addEventListener('storage', handleStorage);
        return () => window.removeEventListener('storage', handleStorage);
    }, []);

    const currentStartup = useMemo(() => {
        if (!user) return null;

        if (startup?.startupId) {
            const fromSystem = systemState.startups.find(s => s.startupId === startup.startupId);
            if (fromSystem) return fromSystem;
        }

        if (user.role === 'founder') {
            return systemState.startups.find(s => s.founderId === user.uid) || null;
        }

        if (['co-founder', 'cofounder'].includes(user.role)) {
            return (
                systemState.startups.find(
                    s => Array.isArray(s.coFounders) && s.coFounders.includes(user.uid)
                ) || null
            );
        }

        return null;
    }, [startup, systemState.startups, user]);

    const myApplications = useMemo(() => {
        if (!currentStartup) return [];
        return systemState.applications.filter(app => app.startupId === currentStartup.startupId);
    }, [systemState.applications, currentStartup]);

    const activeApplicationsCount = useMemo(
        () => myApplications.filter(app => app.status === 'pending').length,
        [myApplications]
    );

    const incubatorCards = useMemo(() => {
        const founderSector = (currentStartup?.sector || '').toLowerCase();
        const founderStage = (currentStartup?.stage || '').toLowerCase();

        return (systemState.incubators || [])
            .map(incubator => {
                const incubatorId = incubator.id || incubator.uid || incubator.incubatorId;
                if (!incubatorId) return null;

                const incubatorCohorts = systemState.cohorts
                    .filter(cohort => cohort.incubatorId === incubatorId)
                    .map(cohort => ({ ...cohort, derivedStatus: getCohortStatus(cohort) }))
                    .sort((a, b) => new Date(a.startDate || 0) - new Date(b.startDate || 0));

                const activeCohort = incubatorCohorts.find(cohort => cohort.derivedStatus === 'active') || null;
                const upcomingCohort = incubatorCohorts.find(cohort => cohort.derivedStatus === 'upcoming') || null;
                const pastCohorts = incubatorCohorts.filter(cohort => cohort.derivedStatus === 'completed');

                let batchTimeline = 'No active cohort';
                if (activeCohort) {
                    batchTimeline = `Batch Active (${formatDate(activeCohort.startDate)} - ${formatDate(activeCohort.endDate)})`;
                } else if (upcomingCohort) {
                    batchTimeline = `Next Batch Starts: ${formatDate(upcomingCohort.startDate)}`;
                }

                const sectorFocus = normalizeToArray(incubator.sectorFocus);
                const stagePreference = normalizeToArray(incubator.stagePreference || incubator.supportedStages);

                const sectorMatch = sectorFocus.some(s => s.toLowerCase() === founderSector);
                const stageMatch = stagePreference.some(s => s.toLowerCase() === founderStage);
                const matchScore = (sectorMatch ? 2 : 0) + (stageMatch ? 1 : 0);

                const relatedApplication = myApplications.find(app => app.incubatorId === incubatorId) || null;

                return {
                    ...incubator,
                    id: incubatorId,
                    name: incubator.name || incubator.incubatorName || 'Unnamed Incubator',
                    location: incubator.location || 'Unknown',
                    sectorFocus,
                    stagePreference,
                    cohorts: incubatorCohorts,
                    activeCohort,
                    upcomingCohort,
                    pastCohorts,
                    activeCapacity: activeCohort ? getCohortCurrentCapacity(activeCohort, systemState.applications) : 0,
                    batchTimeline,
                    successStats: incubator.successStats && Object.keys(incubator.successStats).length > 0 ? incubator.successStats : null,
                    verified: Boolean(incubator.verified),
                    description: incubator.description || '',
                    fundingSupport: Boolean(incubator.fundingSupport),
                    mentors: normalizeToArray(incubator.mentors),
                    relatedApplication,
                    matchScore,
                    isBestMatch: matchScore >= 2,
                    initials: (incubator.name || incubator.incubatorName || 'IN')
                        .split(' ')
                        .filter(Boolean)
                        .map(part => part[0])
                        .join('')
                        .toUpperCase()
                        .slice(0, 2)
                };
            })
            .filter(Boolean)
            .sort((a, b) => {
                if (b.matchScore !== a.matchScore) return b.matchScore - a.matchScore;
                if (a.name && b.name) return a.name.localeCompare(b.name);
                return 0;
            });
    }, [systemState.incubators, systemState.cohorts, systemState.applications, myApplications, currentStartup]);

    const sectorOptions = useMemo(() => {
        const options = new Set(['All']);
        incubatorCards.forEach(card => card.sectorFocus.forEach(sector => options.add(sector)));
        return Array.from(options);
    }, [incubatorCards]);

    const stageOptions = useMemo(() => {
        const options = new Set();
        incubatorCards.forEach(card => card.stagePreference.forEach(stage => options.add(stage)));
        return Array.from(options);
    }, [incubatorCards]);

    const locationOptions = useMemo(() => {
        const options = new Set(['All']);
        incubatorCards.forEach(card => {
            if (card.location) options.add(card.location);
        });
        return Array.from(options);
    }, [incubatorCards]);

    const filteredIncubators = useMemo(() => {
        let result = [...incubatorCards];

        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase();
            result = result.filter(incubator => {
                const searchableSectors = incubator.sectorFocus.join(' ').toLowerCase();
                return (
                    incubator.name.toLowerCase().includes(query) ||
                    incubator.location.toLowerCase().includes(query) ||
                    searchableSectors.includes(query)
                );
            });
        }

        if (filters.sector !== 'All') {
            result = result.filter(incubator => incubator.sectorFocus.includes(filters.sector));
        }

        if (filters.stages.length > 0) {
            result = result.filter(incubator =>
                incubator.stagePreference.some(stage => filters.stages.includes(stage))
            );
        }

        if (filters.location !== 'All') {
            result = result.filter(incubator => incubator.location === filters.location);
        }

        if (filters.verifiedOnly) {
            result = result.filter(incubator => incubator.verified);
        }

        return result;
    }, [incubatorCards, filters, searchQuery]);

    const toggleStageFilter = (stage) => {
        setFilters(prev => ({
            ...prev,
            stages: prev.stages.includes(stage)
                ? prev.stages.filter(item => item !== stage)
                : [...prev.stages, stage]
        }));
    };

    const resetFilters = () => {
        setFilters({
            sector: 'All',
            stages: [],
            location: 'All',
            verifiedOnly: false
        });
        setSearchQuery('');
    };

    const handleApply = (incubator) => {
        if (!currentStartup || !user) return;

        const existing = myApplications.find(app => app.incubatorId === incubator.id);
        if (existing) return;

        const system = getSystem();
        const duplicate = (system.applications || []).find(
            app => app.startupId === currentStartup.startupId && app.incubatorId === incubator.id
        );
        if (duplicate) return;

        const newApplication = {
            id: null,
            founderId: currentStartup.founderId || user.uid,
            startupId: currentStartup.startupId,
            incubatorId: incubator.id,
            startupName: currentStartup.startupName || 'Unnamed Startup',
            sector: currentStartup.sector || 'General',
            teamSize: Number(currentStartup.teamSize) || 1,
            appliedDate: new Date().toISOString(),
            status: 'pending',
            message: ''
        };

        const normalizedApplication = normalizeApplication(newApplication);

        system.applications = [...(system.applications || []), normalizedApplication];
        saveSystem(system);

        setSystemState(prev => ({
            ...prev,
            applications: [...prev.applications, normalizedApplication]
        }));
    };

    const getApplicationState = (incubator) => {
        const application = incubator.relatedApplication;
        if (!application) return { label: 'Apply', tone: 'action' };
        if (application.status === 'accepted') return { label: 'Accepted', tone: 'accepted' };
        if (application.status === 'rejected') return { label: 'Rejected', tone: 'rejected' };
        return { label: 'Applied', tone: 'pending' };
    };

    const isAccessRestricted = !['founder', 'co-founder', 'cofounder'].includes(user?.role);
    const canApply =
        user?.role === 'founder' ||
        (['co-founder', 'cofounder'].includes(user?.role) && startup?.coFounderPermissions?.applications);

    if (loading) return <div className="p-20 text-center text-gray-400">Loading Incubators...</div>;

    if (isAccessRestricted) {
        return (
            <div className="flex flex-col items-center justify-center p-20 bg-[#1E1E2F] rounded-3xl border border-white/5 mx-6">
                <Shield size={48} className="text-red-400 mb-6" />
                <h2 className="text-2xl font-black text-white mb-2">Access Restricted</h2>
                <p className="text-gray-400 text-center max-w-md">
                    Incubator applications are reserved for Founders and Co-Founders.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-10 animate-in fade-in duration-500">
            <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6 px-2 md:px-0">
                <div className="flex-1">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
                        <span className="w-fit px-3 py-1 bg-blue-500/20 text-blue-400 text-[8px] md:text-[10px] font-black uppercase tracking-widest rounded-full border border-blue-500/30">
                            Growth Accelerators
                        </span>
                        <div className="flex items-center gap-2">
                            <span className="w-1 h-1 bg-gray-700 rounded-full" />
                            <span className="text-gray-400 text-[10px] md:text-sm font-medium">Live Discovery</span>
                        </div>
                    </div>
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                        <h1 className="text-3xl md:text-4xl lg:text-5xl font-black text-white tracking-tight">
                            Startup <span className="text-blue-500">Incubators</span>
                        </h1>
                        <button
                            onClick={() => setIsFilterMenuOpen(!isFilterMenuOpen)}
                            className="lg:hidden flex items-center justify-center gap-2 px-6 py-3.5 bg-[#1E1E2F] border border-white/5 rounded-2xl text-white font-bold transition-all hover:bg-white/5"
                        >
                            <Filter size={20} className={isFilterMenuOpen ? 'text-blue-500' : 'text-gray-500'} />
                            <span className="text-sm">Filters</span>
                        </button>
                    </div>
                </div>

                {currentStartup && (
                    <div className="flex items-center gap-2 px-4 py-3 bg-[#1E1E2F] rounded-xl border border-white/5 self-start sm:self-auto">
                        <Target size={16} className="text-blue-500" />
                        <span className="text-xs md:text-sm font-bold text-white">{activeApplicationsCount} Active Applications</span>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <aside className={`${isFilterMenuOpen ? 'block' : 'hidden lg:block'} lg:col-span-1 space-y-6 animate-in slide-in-from-top lg:animate-none`}>
                    <div className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5 shadow-xl">
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="text-lg font-black text-white flex items-center gap-2 uppercase tracking-widest text-[10px]">
                                <Filter size={14} className="text-blue-500" /> Filters
                            </h3>
                            <button
                                onClick={resetFilters}
                                className="text-[10px] font-black text-blue-500 uppercase hover:underline"
                            >
                                Reset
                            </button>
                        </div>

                        <div className="space-y-6">
                            <div className="relative group">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-600 group-focus-within:text-blue-500 transition-colors" size={16} />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder="Search institutions..."
                                    className="w-full bg-[#0F0F14] border border-white/10 rounded-xl py-3 pl-10 pr-4 text-xs text-white placeholder-gray-700 focus:outline-none focus:border-blue-500/30 font-bold"
                                />
                            </div>

                            <div>
                                <label className="text-[10px] text-gray-500 font-black uppercase mb-3 block">Sector Focus</label>
                                <div className="flex flex-wrap gap-2">
                                    {sectorOptions.map((sector) => (
                                        <button
                                            key={sector}
                                            onClick={() => setFilters(prev => ({ ...prev, sector }))}
                                            className={`px-3 py-1.5 rounded-lg text-[10px] font-black border transition-all ${filters.sector === sector
                                                ? 'bg-blue-500/20 border-blue-500/40 text-white'
                                                : 'bg-white/5 border-white/5 text-gray-600 hover:text-white'
                                                }`}
                                        >
                                            {sector}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <label className="text-[10px] text-gray-500 font-black uppercase mb-3 block">Startup Stage</label>
                                <div className="space-y-3">
                                    {stageOptions.map((stage) => (
                                        <div
                                            key={stage}
                                            className="flex items-center gap-3 group cursor-pointer"
                                            onClick={() => toggleStageFilter(stage)}
                                        >
                                            <div className={`w-5 h-5 rounded border flex items-center justify-center transition-all ${filters.stages.includes(stage)
                                                ? 'bg-blue-500 border-blue-500'
                                                : 'border-white/10 group-hover:border-blue-500/50'
                                                }`}>
                                                {filters.stages.includes(stage) && <CheckCircle2 size={12} className="text-white" />}
                                            </div>
                                            <span className={`text-sm font-medium transition-colors ${filters.stages.includes(stage) ? 'text-white' : 'text-gray-400 group-hover:text-white'}`}>
                                                {stage}
                                            </span>
                                        </div>
                                    ))}
                                    {stageOptions.length === 0 && <p className="text-xs text-gray-500">No stage data available.</p>}
                                </div>
                            </div>

                            <div>
                                <label className="text-[10px] text-gray-500 font-black uppercase mb-3 block">Location</label>
                                <select
                                    value={filters.location}
                                    onChange={(e) => setFilters(prev => ({ ...prev, location: e.target.value }))}
                                    className="w-full bg-[#0F0F14] border border-white/10 rounded-xl py-3 px-4 text-xs text-white focus:outline-none focus:border-blue-500/30 font-bold"
                                >
                                    {locationOptions.map(location => (
                                        <option key={location} value={location}>{location}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="pt-4 border-t border-white/5">
                                <label className="flex items-center justify-between cursor-pointer group">
                                    <span className="text-[10px] text-gray-500 font-black uppercase">Verified Only</span>
                                    <div
                                        onClick={() => setFilters(prev => ({ ...prev, verifiedOnly: !prev.verifiedOnly }))}
                                        className={`w-10 h-5 rounded-full relative transition-all ${filters.verifiedOnly ? 'bg-blue-500' : 'bg-[#0F0F14] border border-white/10'}`}
                                    >
                                        <div className={`absolute top-1 w-3 h-3 rounded-full transition-all ${filters.verifiedOnly ? 'right-1 bg-white' : 'left-1 bg-gray-600'}`} />
                                    </div>
                                </label>
                            </div>
                        </div>
                    </div>

                    <div className="p-6 rounded-2xl bg-gradient-to-br from-[#1E1E2F] to-[#0F0F14] border border-blue-500/10 relative overflow-hidden group shadow-lg">
                        <div className="absolute top-0 right-0 p-4 opacity-5"><Globe size={64} /></div>
                        <h4 className="text-white font-bold text-sm mb-2">Relational Sync Active</h4>
                        <p className="text-xs text-gray-500 font-medium mb-4">Cohorts, applications, and startup relevance update in real time.</p>
                        <div className="flex items-center gap-2 text-blue-400 font-black text-[10px] uppercase tracking-widest">
                            <Zap size={10} fill="currentColor" /> Live Data
                        </div>
                    </div>
                </aside>

                <div className="lg:col-span-3 space-y-6">
                    {filteredIncubators.length === 0 ? (
                        <div className="flex flex-col items-center justify-center p-20 bg-[#1E1E2F] rounded-3xl border border-dashed border-white/10 text-center">
                            <RefreshCw size={40} className="text-gray-600 mb-4 animate-spin-slow" />
                            <h3 className="text-xl font-bold text-white mb-2">No institutions match your criteria</h3>
                            <p className="text-gray-400 max-w-sm">Adjust filters to discover relevant incubator programs.</p>
                            <button
                                onClick={resetFilters}
                                className="mt-8 px-8 py-3 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20"
                            >
                                Reset All Filters
                            </button>
                        </div>
                    ) : (
                        filteredIncubators.map((incubator) => {
                            const state = getApplicationState(incubator);
                            const disableApply = state.tone !== 'action' || !canApply || !currentStartup;

                            return (
                                <motion.div
                                    layout
                                    key={incubator.id}
                                    className="bg-[#1E1E2F] p-8 rounded-2xl border border-white/5 group hover:border-blue-500/30 transition-all relative overflow-hidden shadow-xl"
                                >
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/2 blur-[80px] rounded-full translate-x-1/2 -translate-y-1/2 group-hover:bg-blue-500/5 transition-all" />

                                    {incubator.isBestMatch && (
                                        <div className="absolute top-4 left-4 z-10">
                                            <span className="px-2 py-1 bg-blue-600 text-white text-[8px] font-black uppercase rounded-md shadow-lg shadow-blue-600/20">
                                                Best Match
                                            </span>
                                        </div>
                                    )}

                                    <div className="flex flex-col md:flex-row gap-8">
                                        <div className="flex-shrink-0">
                                            <div className="w-20 h-20 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center font-black text-2xl text-gray-400 group-hover:text-blue-400 group-hover:bg-blue-500/10 group-hover:border-blue-500/30 transition-all">
                                                {incubator.initials}
                                            </div>
                                        </div>

                                        <div className="flex-1">
                                            <div className="flex justify-between items-start mb-4 gap-4">
                                                <div>
                                                    <div className="flex items-center gap-2 mb-2">
                                                        <h3 className="text-2xl font-black text-white group-hover:text-blue-400 transition-colors uppercase tracking-tight">
                                                            {incubator.name}
                                                        </h3>
                                                        {incubator.verified && <Shield size={16} className="text-blue-400" />}
                                                    </div>
                                                    <div className="flex flex-wrap items-center gap-4 text-xs font-bold text-gray-500 uppercase tracking-widest">
                                                        <span className="flex items-center gap-1.5"><MapPin size={12} className="text-blue-500" /> {incubator.location}</span>
                                                        <span className="flex items-center gap-1.5"><TrendingUp size={12} className="text-green-500" /> {incubator.sectorFocus.join(', ') || 'General'}</span>
                                                    </div>
                                                </div>

                                                <button
                                                    disabled={disableApply}
                                                    onClick={() => handleApply(incubator)}
                                                    className={`hidden md:flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-black border transition-all shadow-xl ${state.tone === 'accepted' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' :
                                                        state.tone === 'rejected' ? 'bg-rose-500/20 text-rose-400 border-rose-500/30' :
                                                            state.tone === 'pending' ? 'bg-amber-500/20 text-amber-500 border-amber-500/30' :
                                                                !canApply || !currentStartup ? 'bg-gray-800 text-gray-500 cursor-not-allowed border-transparent' :
                                                                    'bg-blue-600 text-white border-blue-600 hover:bg-blue-700 shadow-blue-500/20'
                                                        }`}
                                                >
                                                    {state.tone === 'accepted' ? (
                                                        <>Accepted <CheckCircle2 size={18} /></>
                                                    ) : state.tone === 'rejected' ? (
                                                        <>Rejected <AlertCircle size={18} /></>
                                                    ) : state.tone === 'pending' ? (
                                                        <>Applied <Clock size={18} /></>
                                                    ) : !currentStartup ? (
                                                        'No Startup Linked'
                                                    ) : !canApply ? (
                                                        'Access Locked'
                                                    ) : (
                                                        'Apply'
                                                    )}
                                                </button>
                                            </div>

                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-8 pt-8 border-t border-white/5">
                                                <div className="space-y-4">
                                                    <div>
                                                        <p className="text-[10px] text-gray-600 font-black uppercase mb-1 flex items-center gap-2 tracking-widest">
                                                            <Calendar size={10} /> Batch Timeline
                                                        </p>
                                                        <p className="text-xs font-bold text-gray-300">{incubator.batchTimeline}</p>
                                                    </div>

                                                    {incubator.activeCohort && (
                                                        <div>
                                                            <p className="text-[10px] text-gray-600 font-black uppercase mb-1 flex items-center gap-2 tracking-widest">
                                                                <Users size={10} /> Active Cohort
                                                            </p>
                                                            <p className="text-xs font-bold text-gray-300">
                                                                {incubator.activeCohort.name} ({formatDate(incubator.activeCohort.startDate)} - {formatDate(incubator.activeCohort.endDate)})
                                                            </p>
                                                            <p className="text-[10px] font-semibold text-blue-400 mt-1">
                                                                Capacity: {incubator.activeCapacity}/{Number(incubator.activeCohort.maxCapacity) || 20}
                                                            </p>
                                                        </div>
                                                    )}

                                                    {incubator.successStats && (
                                                        <div>
                                                            <p className="text-[10px] text-gray-600 font-black uppercase mb-1 flex items-center gap-2 tracking-widest">
                                                                <Target size={10} /> Success Metrics
                                                            </p>
                                                            <div className="text-xs font-bold text-gray-300 space-y-1">
                                                                {Object.entries(incubator.successStats).map(([key, value]) => (
                                                                    <p key={key}>{key}: {String(value)}</p>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col justify-end space-y-4">
                                                    <div>
                                                        <p className="text-[10px] text-gray-600 font-black uppercase mb-2 tracking-widest">Target Stages</p>
                                                        <div className="flex flex-wrap gap-2">
                                                            {incubator.stagePreference.map(stage => (
                                                                <span key={stage} className="px-3 py-1 bg-white/5 text-[10px] font-bold text-blue-400 rounded-lg border border-blue-500/10 transition-all">
                                                                    {stage}
                                                                </span>
                                                            ))}
                                                        </div>
                                                    </div>

                                                    <button
                                                        onClick={() => setSelectedIncubator(incubator)}
                                                        className="text-[10px] font-black text-blue-500 uppercase flex items-center gap-2 hover:translate-x-1 transition-transform"
                                                    >
                                                        View Full Details <ChevronRight size={14} />
                                                    </button>
                                                </div>
                                            </div>

                                            <button
                                                disabled={disableApply}
                                                onClick={() => handleApply(incubator)}
                                                className={`md:hidden mt-8 w-full flex items-center justify-center gap-2 py-4 rounded-xl text-sm font-black transition-all ${state.tone === 'accepted'
                                                    ? 'bg-emerald-500/20 text-emerald-400'
                                                    : state.tone === 'rejected'
                                                        ? 'bg-rose-500/20 text-rose-400'
                                                        : state.tone === 'pending'
                                                            ? 'bg-amber-500/20 text-amber-400'
                                                            : !currentStartup || !canApply
                                                                ? 'bg-gray-800 text-gray-500'
                                                                : 'bg-blue-600 text-white shadow-lg'
                                                    }`}
                                            >
                                                {state.label}
                                            </button>
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })
                    )}
                </div>
            </div>

            <AnimatePresence>
                {selectedIncubator && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150] flex items-center justify-center md:p-6"
                    >
                        <motion.div
                            initial={{ y: 50, opacity: 0 }}
                            animate={{ y: 0, opacity: 1 }}
                            exit={{ y: 50, opacity: 0 }}
                            className="bg-[#1E1E2F] w-full h-full md:h-auto md:max-w-4xl md:rounded-3xl border border-white/10 overflow-hidden shadow-2xl overflow-y-auto"
                        >
                            <div className="relative">
                                <div className="h-40 bg-gradient-to-r from-blue-600 to-indigo-700" />
                                <button
                                    onClick={() => setSelectedIncubator(null)}
                                    className="absolute top-4 right-4 p-2 bg-black/20 hover:bg-black/40 rounded-full text-white transition-all"
                                >
                                    <X size={20} />
                                </button>
                                <div className="px-10 -mt-16 mb-8 flex flex-col md:flex-row md:items-end justify-between gap-6">
                                    <div className="flex items-end gap-6">
                                        <div className="w-32 h-32 rounded-3xl bg-[#1E1E2F] border-8 border-[#1E1E2F] overflow-hidden shadow-2xl">
                                            <div className="w-full h-full bg-white/5 flex items-center justify-center text-4xl font-black text-blue-500">
                                                {selectedIncubator.initials}
                                            </div>
                                        </div>
                                        <div className="pb-4">
                                            <div className="flex items-center gap-3 mb-2">
                                                <h2 className="text-3xl font-black text-white uppercase tracking-tight">{selectedIncubator.name}</h2>
                                                {selectedIncubator.verified && <CheckCircle2 size={24} className="text-blue-400" />}
                                            </div>
                                            <p className="text-gray-400 font-bold flex items-center gap-2">
                                                <MapPin size={16} className="text-blue-500" /> {selectedIncubator.location}
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="px-10 pb-10 grid grid-cols-1 md:grid-cols-2 gap-10">
                                <div className="space-y-8">
                                    <section>
                                        <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">About Institution</h4>
                                        <p className="text-gray-300 text-sm leading-relaxed">
                                            {selectedIncubator.description || 'No description available.'}
                                        </p>
                                    </section>

                                    <section>
                                        <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Sector Focus</h4>
                                        <div className="flex flex-wrap gap-2">
                                            {selectedIncubator.sectorFocus.map(sector => (
                                                <span key={sector} className="px-4 py-2 bg-blue-500/10 text-white text-xs font-bold rounded-xl border border-blue-500/20">
                                                    {sector}
                                                </span>
                                            ))}
                                        </div>
                                    </section>

                                    <section>
                                        <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Stage Preference</h4>
                                        <div className="space-y-2">
                                            {selectedIncubator.stagePreference.map(stage => (
                                                <div key={stage} className="flex items-center gap-3 text-sm font-bold text-gray-300">
                                                    <CircleDot size={12} className="text-blue-500" />
                                                    {stage}
                                                </div>
                                            ))}
                                        </div>
                                    </section>

                                    <section>
                                        <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Funding Support</h4>
                                        <p className="text-sm font-bold text-gray-300">
                                            {selectedIncubator.fundingSupport ? 'Available' : 'Not listed'}
                                        </p>
                                    </section>
                                </div>

                                <div className="space-y-8">
                                    <section>
                                        <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Cohorts</h4>
                                        <div className="space-y-3">
                                            {selectedIncubator.activeCohort ? (
                                                <div className="bg-[#0F0F14] p-4 rounded-2xl border border-emerald-500/20">
                                                    <p className="text-[10px] text-emerald-400 font-black uppercase mb-1">Active Cohort</p>
                                                    <p className="text-sm font-bold text-white">{selectedIncubator.activeCohort.name}</p>
                                                    <p className="text-xs text-gray-400">{formatDate(selectedIncubator.activeCohort.startDate)} - {formatDate(selectedIncubator.activeCohort.endDate)}</p>
                                                    <p className="text-xs text-blue-400 mt-1">Capacity {selectedIncubator.activeCapacity}/{Number(selectedIncubator.activeCohort.maxCapacity) || 20}</p>
                                                </div>
                                            ) : (
                                                <div className="bg-[#0F0F14] p-4 rounded-2xl border border-white/10">
                                                    <p className="text-sm font-bold text-gray-300">No active cohort</p>
                                                </div>
                                            )}

                                            {selectedIncubator.upcomingCohort && (
                                                <div className="bg-[#0F0F14] p-4 rounded-2xl border border-blue-500/20">
                                                    <p className="text-[10px] text-blue-400 font-black uppercase mb-1">Upcoming Cohort</p>
                                                    <p className="text-sm font-bold text-white">{selectedIncubator.upcomingCohort.name}</p>
                                                    <p className="text-xs text-gray-400">Starts {formatDate(selectedIncubator.upcomingCohort.startDate)}</p>
                                                </div>
                                            )}

                                            {selectedIncubator.pastCohorts.length > 0 && (
                                                <div className="bg-[#0F0F14] p-4 rounded-2xl border border-white/10">
                                                    <p className="text-[10px] text-gray-400 font-black uppercase mb-2">Past Cohorts</p>
                                                    <div className="space-y-2">
                                                        {selectedIncubator.pastCohorts.map(cohort => (
                                                            <p key={cohort.id} className="text-xs text-gray-300">
                                                                {cohort.name} ({formatDate(cohort.startDate)} - {formatDate(cohort.endDate)})
                                                            </p>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    </section>

                                    {selectedIncubator.mentors.length > 0 && (
                                        <section>
                                            <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Mentors</h4>
                                            <div className="flex flex-wrap gap-2">
                                                {selectedIncubator.mentors.map(mentor => (
                                                    <span key={mentor} className="px-3 py-1 bg-white/5 border border-white/10 rounded-lg text-xs text-gray-300 font-semibold">
                                                        {mentor}
                                                    </span>
                                                ))}
                                            </div>
                                        </section>
                                    )}

                                    {selectedIncubator.successStats && (
                                        <section>
                                            <h4 className="text-[10px] text-blue-500 font-black uppercase tracking-widest mb-4">Success Stats</h4>
                                            <div className="grid grid-cols-2 gap-3">
                                                {Object.entries(selectedIncubator.successStats).map(([key, value]) => (
                                                    <div key={key} className="bg-[#0F0F14] p-4 rounded-xl border border-white/10">
                                                        <p className="text-[10px] text-gray-500 font-black uppercase mb-1">{key}</p>
                                                        <p className="text-sm font-bold text-white">{String(value)}</p>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    )}

                                    <div className="pt-2">
                                        {(() => {
                                            const state = getApplicationState(selectedIncubator);
                                            const disabled = state.tone !== 'action' || !canApply || !currentStartup;

                                            return (
                                                <button
                                                    disabled={disabled}
                                                    onClick={() => handleApply(selectedIncubator)}
                                                    className={`w-full py-4 rounded-2xl font-black transition-all shadow-xl ${state.tone === 'accepted' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/20' :
                                                        state.tone === 'rejected' ? 'bg-rose-500/20 text-rose-400 border border-rose-500/20' :
                                                            state.tone === 'pending' ? 'bg-amber-500/20 text-amber-400 border border-amber-500/20' :
                                                                !currentStartup || !canApply ? 'bg-gray-800 text-gray-500' :
                                                                    'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30'
                                                        }`}
                                                >
                                                    {state.label}
                                                </button>
                                            );
                                        })()}
                                    </div>
                                </div>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default Incubators;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Users,
    CheckCircle2,
    XCircle,
    Clock,
    MessageSquare,
    User,
    ArrowRight,
    Search,
    Filter,
    Mail,
    Calendar,
    Briefcase
} from 'lucide-react';
import { useStartup } from '../../../context/StartupContext';

const JoinRequests = () => {
    const { joinRequests, acceptJoinRequest, rejectJoinRequest, startup } = useStartup();

    // Filter requests for the current startup
    const activeRequests = joinRequests.filter(r => r.startupId === startup?.startupId);

    if (activeRequests.length === 0) {
        return (
            <div className="min-h-[60vh] flex flex-col items-center justify-center text-center animate-in fade-in duration-700">
                <div className="w-20 h-20 rounded-3xl bg-white/5 flex items-center justify-center mb-6 border border-white/5">
                    <Users className="text-gray-600" size={32} />
                </div>
                <h3 className="text-2xl font-black text-white mb-2">No Requests Yet</h3>
                <p className="text-gray-500 max-w-xs font-medium">When co-founders request to join your venture, they will appear here.</p>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-20">
            <div>
                <h1 className="text-4xl font-black text-white tracking-tight">Co-Founder <span className="text-[#8B5CF6]">Requests</span></h1>
                <p className="text-gray-500 mt-2 font-medium">Review talent looking to join your founding team.</p>
            </div>

            <div className="grid grid-cols-1 gap-4">
                <AnimatePresence mode="popLayout">
                    {activeRequests.map((req, index) => (
                        <motion.div
                            key={req.id}
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            transition={{ delay: index * 0.1 }}
                            className="bg-[#1E1E2F] p-8 rounded-[2rem] border border-white/5 flex flex-col md:flex-row items-center gap-8 group hover:border-[#8B5CF6]/30 transition-all shadow-xl"
                        >
                            {/* Avatar */}
                            <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-[#8B5CF6] to-indigo-600 flex items-center justify-center font-black text-3xl text-white shadow-lg group-hover:scale-110 transition-transform duration-500 shrink-0">
                                {req.requesterName[0]}
                            </div>

                            {/* Info */}
                            <div className="flex-1 space-y-4 text-center md:text-left">
                                <div>
                                    <div className="flex items-center justify-center md:justify-start gap-3 mb-1">
                                        <h3 className="text-2xl font-black text-white">{req.requesterName}</h3>
                                        <span className="px-2 py-0.5 bg-[#8B5CF6]/10 text-[#8B5CF6] text-[10px] font-black uppercase rounded border border-[#8B5CF6]/20">
                                            Candidate
                                        </span>
                                    </div>
                                    <div className="flex flex-wrap justify-center md:justify-start gap-4 text-xs font-bold text-gray-500 uppercase tracking-widest">
                                        <span className="flex items-center gap-1.5"><Calendar size={14} /> {new Date(req.createdAt).toLocaleDateString()}</span>
                                        <span className="flex items-center gap-1.5"><Clock size={14} /> {new Date(req.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                    </div>
                                </div>

                                <div className="p-4 bg-white/5 rounded-2xl border border-white/5 relative">
                                    <MessageSquare size={16} className="absolute -top-2 -left-2 text-[#8B5CF6]" />
                                    <p className="text-sm text-gray-300 leading-relaxed italic">
                                        "{req.message || "No message provided."}"
                                    </p>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="flex flex-row md:flex-col gap-3 shrink-0">
                                {req.status === 'pending' ? (
                                    <>
                                        <button
                                            onClick={() => acceptJoinRequest(req.id)}
                                            className="px-6 py-3 bg-[#8B5CF6] hover:bg-[#7C3AED] text-white text-xs font-black uppercase rounded-xl shadow-lg shadow-[#8B5CF6]/20 transition-all flex items-center gap-2"
                                        >
                                            <CheckCircle2 size={16} /> Accept
                                        </button>
                                        <button
                                            onClick={() => rejectJoinRequest(req.id)}
                                            className="px-6 py-3 bg-white/5 hover:bg-rose-500/10 text-gray-500 hover:text-rose-400 text-xs font-black uppercase rounded-xl transition-all flex items-center gap-2"
                                        >
                                            <XCircle size={16} /> Decline
                                        </button>
                                    </>
                                ) : (
                                    <div className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border ${req.status === 'accepted' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                                        }`}>
                                        {req.status === 'accepted' ? <CheckCircle2 size={16} /> : <XCircle size={16} />}
                                        {req.status}
                                    </div>
                                )}
                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        </div>
    );
};

export default JoinRequests;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import {
    Briefcase,
    Search,
    Filter,
    MessageSquare,
    Star,
    ChevronRight,
    X,
    Shield,
    Calendar,
    ArrowRight,
    MapPin,
    Target,
    Plus,
    RefreshCw,
    User,
    CheckCircle2,
    Zap,
    Activity,
    Rocket,
    Clock
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../../../context/AuthContext';
import { useStartup } from '../../../context/StartupContext';
import { useLocation, useNavigate } from 'react-router-dom';
import { getMentorUsers, getSystem } from '../../../utils/system';

const normalizeSectorLabel = (value) => {
    const normalized = (value || '').toString().trim().toLowerCase();
    const map = {
        tech: 'Technology',
        technology: 'Technology',
        finance: 'Finance',
        fintech: 'Fintech',
        marketing: 'Marketing',
        operations: 'Operations',
        general: 'General',
        ai: 'AI/ML',
        'ai/ml': 'AI/ML',
        saas: 'SaaS',
        edtech: 'Edtech',
        healthtech: 'Healthtech'
    };

    if (!normalized) return 'General';
    return map[normalized] || value;
};

const Mentors = () => {
    const { user } = useAuth();
    const { startup, requestMentorship, mentorRequests, removeAssignedMentor } = useStartup();
    const location = useLocation();
    const navigate = useNavigate();
    const role = user?.role === 'co-founder' ? 'co-founder' : 'founder';

    // --- State Management ---
    const [activeTab, setActiveTab] = useState('explore'); // 'explore' | 'my-mentor'
    const [mentors, setMentors] = useState([]);
    const [selectedMentor, setSelectedMentor] = useState(null);
    const [requestingMentor, setRequestingMentor] = useState(null);
    const [loading, setLoading] = useState(true);

    const closeProfileModal = () => setSelectedMentor(null);
    const closeRequestModal = () => setRequestingMentor(null);

    // Sync active tab with location hash
    useEffect(() => {
        if (location.hash === '#my-mentor' && startup?.mentorAssigned) {
            setActiveTab('my-mentor');
        } else {
            setActiveTab('explore');
        }
    }, [location.hash, startup?.mentorAssigned]);

    // Filter State
    const [filters, setFilters] = useState({
        sector: 'All',
        stages: [],
        expertise: 'All',
        verifiedOnly: false
    });
    const [isFilterMenuOpen, setIsFilterMenuOpen] = useState(false);
    const modalRef = useRef(null);
    const requestModalRef = useRef(null);

    // Scroll modal to top when opening
    useEffect(() => {
        if (selectedMentor && modalRef.current) {
            modalRef.current.scrollTo(0, 0);
        }
    }, [selectedMentor]);

    useEffect(() => {
        if (requestingMentor && requestModalRef.current) {
            requestModalRef.current.scrollTo(0, 0);
        }
    }, [requestingMentor]);

    // Keep modal exits consistent across desktop and mobile.
    useEffect(() => {
        const onEsc = (event) => {
            if (event.key !== 'Escape') return;

            if (requestingMentor) {
                closeRequestModal();
                return;
            }

            if (selectedMentor) {
                closeProfileModal();
            }
        };

        if (selectedMentor || requestingMentor) {
            window.addEventListener('keydown', onEsc);
        }

        return () => {
            window.removeEventListener('keydown', onEsc);
        };
    }, [selectedMentor, requestingMentor]);

    // Request Form State
    const [requestForm, setRequestForm] = useState({
        problem: '',
        tried: '',
        outcome: ''
    });

    // --- Initialization ---
    useEffect(() => {
        const refreshData = () => {
            setLoading(true);
            try {
                // Fetch mentors from global system
                const system = getSystem();
                const allUsers = system.users || {};

                const toArray = (value) => {
                    if (Array.isArray(value)) return value.filter(Boolean);
                    if (typeof value === 'string') {
                        return value
                            .split(',')
                            .map((item) => item.trim())
                            .filter(Boolean);
                    }
                    return [];
                };

                const stageLabel = (value) => {
                    const normalized = (value || '').toString().trim().toLowerCase();
                    const map = {
                        idea: 'Idea',
                        validation: 'Validation',
                        mvp: 'MVP',
                        revenue: 'Revenue',
                        scale: 'Scale'
                    };
                    return map[normalized] || null;
                };

                const mentorsList = getMentorUsers({ users: allUsers })
                    .map((m, idx) => ({
                        ...(() => {
                            const rawFocusAreas = toArray(m.profileData?.focusAreas || m.expertise || m.primarySkills);
                            const normalizedStage = stageLabel(m.profileData?.stageSupport || m.stageSupport || m.stage);
                            const stages = Array.isArray(m.profileData?.supportedStages)
                                ? m.profileData.supportedStages
                                : normalizedStage
                                    ? [normalizedStage]
                                    : ['Idea', 'MVP', 'Revenue'];

                            const experienceYears = Number(m.profileData?.yearsExp || m.yearsExp);
                            const experienceText = Number.isFinite(experienceYears) && experienceYears > 0
                                ? `${experienceYears}+ Years of Mentorship`
                                : (m.profileData?.experience || m.experience || 'Experienced Startup Mentor');

                            return {
                                focusAreas: rawFocusAreas.length > 0 ? rawFocusAreas : ['Strategy', 'Product', 'Fundraising'],
                                supportedStages: stages,
                                expertiseSector: normalizeSectorLabel(m.profileData?.expertiseSector || m.expertiseSector || m.industry),
                                shortBio: m.profileData?.shortBio || m.bio || 'Professional mentor helping startups scale.',
                                experience: experienceText,
                                title: m.profileData?.currentRole || m.profileData?.title || m.title || 'Expert Mentor'
                            };
                        })(),
                        id: m.uid || `mentor-${idx}`,
                        name: m.name || m.profileData?.fullName || m.email.split('@')[0],
                        initials: (m.name || m.email.split('@')[0]).split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2),
                        mentorshipFocus: m.profileData?.mentorshipFocus || 'Scaling & Growth',
                        expertise: Array.isArray(m.expertise) ? m.expertise : [],
                        responseRate: m.profileData?.responseRate || 95,
                        verified: (m.badge || '').toLowerCase() === 'verified' || m.profileData?.verified === true,
                        badge: m.badge || m.profileData?.badge || 'Verified',
                        availabilityStatus: m.availability?.status || m.profileData?.availability?.status || 'Available',
                        availability: m.availability || m.profileData?.availability || { status: 'Available', days: [], workload: 0, sessionType: '1:1' },
                        capacity: Number(m.portalData?.capacity) || 5,
                        totalMentees: m.profileData?.totalMentees || 0,
                        rating: m.profileData?.rating || 5.0,
                        mentorshipStyle: m.profileData?.mentorshipStyle || 'Direct & Strategic with a focus on measurable KPIs.',
                        mentorshipHistory: m.profileData?.mentorshipHistory || [
                            { company: 'Nexus AI', result: 'Seed to Series A', stage: 'Scaling' },
                            { company: 'SwiftPay', result: 'Acquired by Stripe', stage: 'Exit' },
                            { company: 'EduFlow', result: '10x User Growth', stage: 'Growth' }
                        ]
                    }));
                setMentors(mentorsList);
            } catch (err) {
                console.error("Error fetching mentors:", err);
            } finally {
                setLoading(false);
            }
        };

        refreshData();
        const handleStorage = () => refreshData();
        window.addEventListener('storage', handleStorage);
        return () => window.removeEventListener('storage', handleStorage);
    }, [user.uid]);

    // --- Logic: Dynamic Response Rate ---
    const processedMentors = useMemo(() => {
        const system = getSystem();
        const allRequests = system.mentorRequests || [];
        const allStartups = system.startups || [];
        return mentors.map(m => {
            const mentorRequests = allRequests.filter(r => r.mentorId === m.id);
            const acceptedRequests = mentorRequests.filter(r => r.status === 'accepted').length;
            const assignedStartups = allStartups.filter(startupItem => startupItem.mentorAssigned === m.id).length;

            let calculatedRate = m.responseRate;
            if (mentorRequests.length > 0) {
                const ratio = acceptedRequests / mentorRequests.length;
                calculatedRate = Math.floor(70 + (ratio * 28)); // Adjusted math for realistic premium feel
            }

            return {
                ...m,
                dynamicResponseRate: calculatedRate,
                assignedStartups,
                workload: `${assignedStartups}/${m.capacity}`
            };
        });
    }, [mentors]);

    // --- Logic: Premium Matching & Filtering ---
    const filteredMentors = useMemo(() => {
        let result = [...processedMentors];

        if (filters.sector !== 'All') {
            result = result.filter(m => m.expertiseSector === filters.sector);
        }

        if (filters.stages.length > 0) {
            result = result.filter(m =>
                m.supportedStages.some(stage => filters.stages.includes(stage))
            );
        }

        if (filters.expertise !== 'All') {
            result = result.filter(m =>
                m.expertise.includes(filters.expertise) || m.focusAreas.includes(filters.expertise)
            );
        }

        if (filters.verifiedOnly) {
            result = result.filter(m => m.verified);
        }

        const founderSector = normalizeSectorLabel(startup?.sector || startup?.expertiseSector || '');
        const founderStage = startup?.stage || 'Idea';

        result = result.map(m => {
            const sectorMatch = m.expertiseSector === founderSector;
            const stageMatch = m.supportedStages.includes(founderStage);
            const matchScore = (sectorMatch ? 2 : 0) + (stageMatch ? 1 : 0);
            return { ...m, matchScore, isBestMatch: matchScore >= 2 };
        });

        result.sort((a, b) => {
            if (b.matchScore !== a.matchScore) return b.matchScore - a.matchScore;
            return b.dynamicResponseRate - a.dynamicResponseRate;
        });

        return result;
    }, [processedMentors, filters, startup]);

    const sectorOptions = useMemo(() => {
        return ['All', ...new Set(processedMentors.map(mentor => mentor.expertiseSector).filter(Boolean))];
    }, [processedMentors]);

    // --- Helpers ---
    const toggleStageFilter = (stage) => {
        setFilters(prev => ({
            ...prev,
            stages: prev.stages.includes(stage)
                ? prev.stages.filter(s => s !== stage)
                : [...prev.stages, stage]
        }));
    };

    const resetFilters = () => {
        setFilters({
            sector: 'All',
            stages: [],
            expertise: 'All',
            verifiedOnly: false
        });
    };

    const handleRequestSubmit = (e) => {
        e.preventDefault();

        const message = `Problem: ${requestForm.problem}\n\nTried: ${requestForm.tried}\n\nOutcome: ${requestForm.outcome}`;
        requestMentorship(requestingMentor.id, message);

        setRequestForm({ problem: '', tried: '', outcome: '' });
        setRequestingMentor(null);
    };

    const hasRequested = (mentorId) => {
        const system = getSystem();
        return (system.mentorRequests || []).some(r => r.mentorId === mentorId && r.startupId === startup?.startupId && r.status === 'pending');
    };

    const isAccessRestricted = !['founder', 'co-founder'].includes(user?.role);
    const canRequest = user?.role === 'founder' && !!startup || (user?.role === 'co-founder' && startup?.coFounderPermissions?.mentorship);

    const expertiseOptions = useMemo(() => {
        return ['All', ...new Set(processedMentors.flatMap(mentor => mentor.expertise || []).filter(Boolean))];
    }, [processedMentors]);

    if (loading) return (
        <div className="min-h-[60vh] flex flex-col items-center justify-center gap-4">
            <RefreshCw size={32} className="text-[#8B5CF6] animate-spin" />
            <p className="text-gray-500 font-bold tracking-widest uppercase text-[10px]">Loading Vanguard Network...</p>
        </div>
    );

    if (isAccessRestricted || (user?.role === 'founder' && !startup)) {
        return (
            <div className="flex flex-col items-center justify-center p-20 bg-[#1E1E2F] rounded-3xl border border-white/5 mx-6">
                <Shield size={48} className="text-[#8B5CF6] mb-6" />
                <h2 className="text-2xl font-black text-white mb-2">{!startup ? 'Startup Required' : 'Access Restricted'}</h2>
                <p className="text-gray-400 text-center max-w-md">
                    {!startup
                        ? 'You must create or join a startup before you can request mentorship from the Vanguard network.'
                        : 'The Vanguard Mentorship system is exclusive to Founders and authorized Co-Founders.'}
                </p>
                {!startup && user?.role === 'founder' && (
                    <button
                        onClick={() => navigate('/founder/dashboard')}
                        className="mt-8 px-8 py-3 bg-[#8B5CF6] text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-indigo-600 transition-all"
                    >
                        Go to Dashboard
                    </button>
                )}
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header & Tabs */}
            <div className="flex flex-col gap-8">
                <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6 px-2 md:px-0">
                    <div className="flex-1">
                        <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
                            <span className="w-fit px-3 py-1 bg-[#8B5CF6]/20 text-[#8B5CF6] text-[8px] md:text-[10px] font-black uppercase tracking-widest rounded-full border border-[#8B5CF6]/30 shadow-lg shadow-[#8B5CF6]/5">
                                Expert Global Network
                            </span>
                            <div className="flex items-center gap-2">
                                <span className="w-1 h-1 bg-gray-700 rounded-full" />
                                <span className="text-gray-400 text-[10px] md:text-sm font-medium tracking-tight">Access Top-Tier Strategic Advisors</span>
                            </div>
                        </div>
                        <h1 className="text-3xl md:text-4xl lg:text-5xl font-black text-white tracking-tight leading-tight">
                            Vanguard <span className="text-transparent bg-clip-text bg-gradient-to-r from-[#8B5CF6] to-purple-400">Mentors</span>
                        </h1>
                    </div>

                    <div className="flex items-center gap-4">
                        {(mentorRequests || []).length > 0 && (
                            <div className="flex items-center gap-3 px-5 py-4 bg-[#8B5CF6]/5 rounded-2xl border border-[#8B5CF6]/20 shadow-xl">
                                <div className="w-2 h-2 rounded-full bg-[#8B5CF6] animate-pulse" />
                                <span className="text-xs md:text-sm font-bold text-[#8B5CF6] tracking-tight">{(mentorRequests || []).length} Requests Pending</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* Tab Navigation */}
                <div className="flex items-center gap-4 p-1.5 bg-[#1E1E2F] rounded-[2rem] w-fit border border-white/5 mx-2 md:mx-0">
                    <button
                        onClick={() => setActiveTab('explore')}
                        className={`flex items-center gap-2 px-8 py-3.5 rounded-[1.7rem] text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'explore'
                            ? 'bg-[#8B5CF6] text-white shadow-xl shadow-[#8B5CF6]/20'
                            : 'text-gray-500 hover:text-white'
                            }`}
                    >
                        <Search size={16} /> Explore Mentors
                    </button>
                    <button
                        onClick={() => setActiveTab('my-mentor')}
                        className={`flex items-center gap-2 px-8 py-3.5 rounded-[1.7rem] text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'my-mentor'
                            ? 'bg-[#8B5CF6] text-white shadow-xl shadow-[#8B5CF6]/20'
                            : 'text-gray-500 hover:text-white'
                            }`}
                    >
                        <User size={16} /> My Mentor
                    </button>
                </div>
            </div>

            {activeTab === 'explore' ? (
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                    {/* Global Filters */}
                    <aside className={`${isFilterMenuOpen ? 'block' : 'hidden lg:block'} lg:col-span-1 space-y-6 animate-in slide-in-from-top lg:animate-none`}>
                        <div className="bg-[#1E1E2F] p-8 rounded-3xl border border-white/5 shadow-2xl sticky top-8">
                            <div className="flex items-center justify-between mb-8 text-white">
                                <h3 className="text-lg font-black flex items-center gap-3 uppercase tracking-[0.2em] text-[10px]">
                                    <Filter size={14} className="text-[#8B5CF6]" /> Filter Profile
                                </h3>
                                <button
                                    onClick={resetFilters}
                                    className="text-[10px] font-black text-[#8B5CF6] uppercase hover:underline hover:text-white transition-colors"
                                >
                                    Reset All
                                </button>
                            </div>

                            <div className="space-y-8">
                                {/* Sector Filter */}
                                <div>
                                    <label className="text-[10px] text-gray-500 font-black uppercase mb-3 block tracking-widest pl-1">Sector Focus</label>
                                    <select
                                        value={filters.sector}
                                        onChange={(e) => setFilters({ ...filters, sector: e.target.value })}
                                        className="w-full bg-[#0F0F14] border border-white/10 rounded-2xl p-4 text-sm text-gray-300 focus:outline-none focus:border-[#8B5CF6]/50 transition-all cursor-pointer"
                                    >
                                        {sectorOptions.map((sector) => (
                                            <option key={sector} value={sector}>{sector === 'All' ? 'All Sectors' : sector}</option>
                                        ))}
                                    </select>
                                </div>
                                {/* Expertise Filter */}
                                <div>
                                    <label className="text-[10px] text-gray-500 font-black uppercase mb-3 block tracking-widest pl-1">Expertise</label>
                                    <select
                                        value={filters.expertise}
                                        onChange={(e) => setFilters({ ...filters, expertise: e.target.value })}
                                        className="w-full bg-[#0F0F14] border border-white/10 rounded-2xl p-4 text-sm text-gray-300 focus:outline-none focus:border-[#8B5CF6]/50 transition-all cursor-pointer"
                                    >
                                        {expertiseOptions.map((expertise) => (
                                            <option key={expertise} value={expertise}>{expertise === 'All' ? 'All Expertise' : expertise}</option>
                                        ))}
                                    </select>
                                </div>

                                {/* Stage Filter */}
                                <div>
                                    <label className="text-[10px] text-gray-500 font-black uppercase mb-4 block tracking-widest pl-1">Target Startup Stage</label>
                                    <div className="space-y-4">
                                        {['Idea', 'Validation', 'MVP', 'Revenue', 'Scale'].map(st => (
                                            <div
                                                key={st}
                                                className="flex items-center gap-3 group cursor-pointer"
                                                onClick={() => toggleStageFilter(st)}
                                            >
                                                <div className={`w-5 h-5 rounded-lg border flex items-center justify-center transition-all ${filters.stages.includes(st)
                                                    ? 'bg-[#8B5CF6] border-[#8B5CF6] shadow-lg shadow-[#8B5CF6]/20'
                                                    : 'border-white/10 group-hover:border-[#8B5CF6]/50 bg-[#0F0F14]'
                                                    }`}>
                                                    {filters.stages.includes(st) && <CheckCircle2 size={12} className="text-white" />}
                                                </div>
                                                <span className={`text-[13px] font-bold transition-colors ${filters.stages.includes(st) ? 'text-white' : 'text-gray-500 group-hover:text-white'
                                                    }`}>{st} Stage</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>

                                {/* Verified Toggle */}
                                <div className="pt-6 border-t border-white/5">
                                    <label className="flex items-center justify-between cursor-pointer group">
                                        <span className="text-[11px] text-gray-400 font-bold">Vanguard Verified</span>
                                        <div
                                            onClick={() => setFilters({ ...filters, verifiedOnly: !filters.verifiedOnly })}
                                            className={`w-12 h-6 rounded-full relative transition-all duration-300 ${filters.verifiedOnly ? 'bg-[#8B5CF6]' : 'bg-[#0F0F14] border border-white/10'}`}
                                        >
                                            <div className={`absolute top-1 w-4 h-4 rounded-full transition-all duration-300 ${filters.verifiedOnly ? 'right-1 bg-white shadow-md' : 'left-1 bg-gray-700'}`} />
                                        </div>
                                    </label>
                                </div>
                            </div>
                        </div>

                        <div className="bg-gradient-to-br from-[#8B5CF6]/20 to-purple-900/10 p-8 rounded-3xl border border-[#8B5CF6]/30 relative overflow-hidden group">
                            <div className="absolute -right-4 -bottom-4 opacity-[0.05] group-hover:scale-110 transition-transform duration-700">
                                <Target size={120} />
                            </div>
                            <h4 className="font-black text-white text-sm mb-3 flex items-center gap-2 relative z-10">
                                <Star size={14} className="text-[#8B5CF6]" fill="currentColor" /> Strategic Ranking
                            </h4>
                            <p className="text-[11px] text-gray-400 font-medium leading-relaxed relative z-10">
                                The network is currently optimized to surface mentors who specialize in <span className="text-white font-bold">{startup?.stage || 'Idea'}</span> stage startups within the <span className="text-white font-bold">{normalizeSectorLabel(startup?.sector || startup?.expertiseSector || 'General')}</span> sector.
                            </p>
                        </div>
                    </aside>

                    {/* Mentor Cards */}
                    <div className="lg:col-span-3">
                        {filteredMentors.length === 0 ? (
                            <div className="flex flex-col items-center justify-center p-20 bg-[#1E1E2F] rounded-[2.5rem] border border-dashed border-white/10 text-center">
                                <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center mb-8 text-gray-700">
                                    <Search size={40} />
                                </div>
                                <h3 className="text-2xl font-black text-white mb-2">Boundary Exceeded</h3>
                                <p className="text-gray-500 max-w-sm font-medium">No mentors currently match your specific strategic filters. Try expanding your search criteria.</p>
                                <button
                                    onClick={resetFilters}
                                    className="mt-8 px-8 py-4 bg-[#8B5CF6] text-white text-xs font-black uppercase tracking-widest rounded-2xl hover:bg-[#7C3AED] transition-all shadow-xl shadow-[#8B5CF6]/20"
                                >
                                    Reset Search Parameters
                                </button>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
