                        if (!myMentor) return null;

                        const system = getSystem();
                        const mySessions = (system.sessions || []).filter(s => s.startupId === startup.startupId);
                        const nextSession = mySessions.find(s => s.status === 'upcoming' || s.status === 'pending_confirmation');

