                                                        Remove Mentor
                                                    </button>
                                                    <button
                                                        onClick={() => setSelectedMentor(myMentor)}
                                                        className="px-8 py-4 bg-white/5 text-gray-400 text-[10px] font-black uppercase tracking-widest rounded-2xl border border-white/5 hover:text-white transition-all"
                                                    >
                                                        Performance Data
                                                    </button>
                                                </div>
                                            </div>
                                        </div>

